def check_length(lines):
    return [(i, 'Line exceeds 80 characters (%d)' % len(line))
            for i, line in enumerate(lines) if len(line) > 80]


def check_trailing_space(lines):
    return [(i, 'Line ends in whitespace') for i, line in enumerate(lines)
            if line and line[-1].isspace()]


def check_indent(lines):
    errors = []
    for i, line in enumerate(lines):
        stripped = line.lstrip(' ')
        indent = len(line) - len(stripped)
        if stripped and indent % 4 != 0:
            errors.append((i, 'Indent of %d is not a multiple of 4' % indent))
    return errors


def check_todo(lines):
    return [(i, 'Line contains TODO') for i, line in enumerate(lines)
            if 'TODO' in line]


def check_consecutive_blank(lines):
    return [(i, 'Consecutive blank lines') for i, line in enumerate(lines)
            if i > 0 and not line.strip() and not lines[i - 1].strip()]


def check_print(lines):
    return [(i, 'Line contains print(') for i, line in enumerate(lines)
            if 'print(' in line]


def check_semicolon(lines):
    errors = []
    for i, line in enumerate(lines):
        content = line.rstrip()
        if content and not content.endswith(';'):
            errors.append((i, 'Statement does not end in ";"'))
    return errors


def generate_report(lines):
    parts = []
    for i, line in enumerate(lines):
        safe = line.replace('&', '&amp;').replace('<', '&lt;')
        parts.append('<div>Line %d: %s</div>' % (i, safe.replace('>', '&gt;')))
    return ''.join(parts)


ALL_CHECKS = (check_length, check_trailing_space, check_indent, check_todo,
              check_consecutive_blank, check_print, check_semicolon)


def lint(lines):
    findings = []
    for check in ALL_CHECKS:
        findings.extend(check(lines))
    findings.sort(key=lambda item: item[0])
    return findings


def main():
    source = [
        'x = 1',
        'print(x)',
        '  y = 2;   ',
        '',
        '',
        '    z = x + y; # TODO refine',
        'w = "' + 'a' * 90 + '";',
    ]
    for line_no, message in lint(source):
        print('line %d: %s' % (line_no, message))
    print(generate_report(source))


if __name__ == '__main__':
    main()

