import math


def calc_segments(path):
    segments = []
    for i, point in enumerate(path):
        if i == 0:
            continue
        px, py = path[i - 1]
        segments.append((i - 1, math.hypot(point[0] - px, point[1] - py)))
    return segments


def find_sharp_turns(path):
    sharp = []
    for i, point in enumerate(path):
        if i == 0 or i == len(path) - 1:
            continue
        ax = point[0] - path[i - 1][0]
        ay = point[1] - path[i - 1][1]
        bx = path[i + 1][0] - point[0]
        by = path[i + 1][1] - point[1]
        na = math.hypot(ax, ay)
        nb = math.hypot(bx, by)
        if na == 0 or nb == 0:
            continue
        cos_t = max(-1.0, min(1.0, (ax * bx + ay * by) / (na * nb)))
        if math.degrees(math.acos(cos_t)) > 90:
            sharp.append(i)
    return sharp


def bounding_boxes(path):
    boxes = []
    for i, window_start in enumerate(path[:-2]):
        window = [window_start, path[i + 1], path[i + 2]]
        xs = [p[0] for p in window]
        ys = [p[1] for p in window]
        boxes.append((i, (min(xs), min(ys), max(xs), max(ys))))
    return boxes


def simplify_path(path):
    collinear = []
    for i, point in enumerate(path):
        if i == 0 or i == len(path) - 1:
            continue
        ax = point[0] - path[i - 1][0]
        ay = point[1] - path[i - 1][1]
        bx = path[i + 1][0] - point[0]
        by = path[i + 1][1] - point[1]
        if abs(ax * by - ay * bx) < 1e-9:
            collinear.append(i)
    return collinear


def export_svg(path):
    return ["<circle id='pt_{}' cx='{}' cy='{}'/>".format(i, x, y)
            for i, (x, y) in enumerate(path)]


def export_obj(path):
    lines = []
    for i, (x, y) in enumerate(path):
        lines.append("# vertex {}".format(i))
        lines.append("v {} {} 0".format(x, y))
    return lines


def find_intersections(path, line):
    return [(i, point) for i, point in enumerate(path) if abs(point[1] - line) < 1e-9]


def closest_points(path, target):
    tx, ty = target
    result = [(i, math.hypot(x - tx, y - ty)) for i, (x, y) in enumerate(path)]
    return sorted(result, key=lambda pair: pair[1])


def main():
    path = [(0, 0), (5, 0), (10, 0), (10, 10), (0, 5)]
    for index, length in calc_segments(path):
        print("segment {}: {:.2f}".format(index, length))
    print("sharp turns:", find_sharp_turns(path))
    for index, box in bounding_boxes(path):
        print("bbox {}: {}".format(index, box))
    print("collinear:", simplify_path(path))
    for line in export_svg(path) + export_obj(path):
        print(line)
    print("on y=0:", find_intersections(path, 0))
    for index, dist in closest_points(path, (0, 0)):
        print("point {} at {:.2f}".format(index, dist))


if __name__ == "__main__":
    main()

