def find_404(logs):
    for index, log in enumerate(logs):
        if log.split()[-1] == '404':
            yield index, log


def detect_rapid_requests(logs):
    previous_ip = None
    for index, log in enumerate(logs):
        current_ip = log.split()[0]
        if current_ip == previous_ip:
            yield index
        previous_ip = current_ip


def find_unauthorized(logs):
    return [index for index, log in enumerate(logs) if '401' in log]


def extract_ips(logs):
    for index, log in enumerate(logs):
        yield index, log.split()[0]


def format_html_report(logs):
    for index, log in enumerate(logs):
        yield "<div id='log_{}'>{}</div>".format(index, log)


def find_admin_access(logs):
    matches = []
    for index, log in enumerate(logs):
        fields = log.split()
        if len(fields) >= 3 and '/admin' in fields[2]:
            matches.append((index, log))
    return matches


def detect_malformed(logs):
    return [index for index, log in enumerate(logs) if log.count(' ') != 3]


def generate_syslog(logs):
    for index, log in enumerate(logs):
        yield '[{}] {}'.format(index, log)


def main():
    logs = [
        '10.0.0.1 GET / 200',
        '10.0.0.1 GET /admin 401',
        '10.0.0.2 POST /login 404',
        '10.0.0.2 GET /admin/panel 200',
        '192.168.1.5 GET /index.html',
        '10.0.0.3 DELETE /files 404',
    ]

    print('Missing pages:')
    for line_number, log in find_404(logs):
