def find_404(logs):
    for index in range(len(logs)):
        if logs[index].split()[-1] == '404':
            yield index, logs[index]


def detect_rapid_requests(logs):
    previous_ip = None
    for index in range(len(logs)):
        current_ip = logs[index].split()[0]
        if current_ip == previous_ip:
            yield index
        previous_ip = current_ip


def find_unauthorized(logs):
    return [index for index in range(len(logs)) if '401' in logs[index]]


def extract_ips(logs):
    for index in range(len(logs)):
        yield index, logs[index].split()[0]


def format_html_report(logs):
    for index in range(len(logs)):
        yield "<div id='log_{}'>{}</div>".format(index, logs[index])


def find_admin_access(logs):
    matches = []
    for index in range(len(logs)):
        fields = logs[index].split()
        if len(fields) >= 3 and '/admin' in fields[2]:
            matches.append((index, logs[index]))
    return matches


def detect_malformed(logs):
    return [index for index in range(len(logs)) if logs[index].count(' ') != 3]


def generate_syslog(logs):
    for index in range(len(logs)):
