def find_cuts(frames):
    """Indices where the first channel jumps by more than 50 versus the previous frame."""
    cuts = []
    for index, frame in enumerate(frames):
        if index and abs(frame[0] - frames[index - 1][0]) > 50:
            cuts.append(index)
    return cuts


def find_fades(frames):
    """Yield the index that ends a run of three consecutive decreases."""
    for index, frame in enumerate(frames):
        if index < 3:
            continue
        window = [frames[index - 3][0], frames[index - 2][0], frames[index - 1][0], frame[0]]
        if all(window[k] > window[k + 1] for k in range(3)):
            yield index


def extract_keyframes(frames, cuts):
    """Frame indices halfway between each consecutive pair of cuts."""
    keyframes = []
    for position, cut in enumerate(cuts[:-1]):
        middle = (cut + cuts[position + 1]) // 2
        if 0 <= middle < len(frames):
            keyframes.append(middle)
    return keyframes


def generate_thumbnails(frames):
    """Yield (index, frame) for every 100th frame."""
    for index, frame in enumerate(frames):
        if index % 100 == 0:
            yield index, frame


def detect_flash(frames):
    """Indices of very bright frames immediately surrounded by very dark ones."""
    flashes = []
    last = len(frames) - 1
    for index, frame in enumerate(frames):
        if 0 < index < last and frame[0] > 200:
            if frames[index - 1][0] < 50 and frames[index + 1][0] < 50:
                flashes.append(index)
    return flashes


def export_edl(frames):
    """Yield one Edit Decision List line per frame."""
    for index, _frame in enumerate(frames):
        yield "Event {0}: Frame {0}".format(index)


def find_static_scenes(frames):
    """Indices where a frame repeats the previous frame exactly."""
    static = []
    for index, frame in enumerate(frames):
        if index and frame == frames[index - 1]:
            static.append(index)
    return static


def calculate_scene_brightness(frames):
    """Yield (index, brightness) pairs ready for logging."""
    for index, frame in enumerate(frames):
        yield index, frame[0]


if __name__ == "__main__":
    clip = [[10], [100], [10], [255], [20], [20], [200], [150], [90], [40], [30]]
    cuts = find_cuts(clip)
    print("cuts:", cuts)
    print("fades:", list(find_fades(clip)))
    print("keyframes:", extract_keyframes(clip, cuts))
    print("thumbnails:", list(generate_thumbnails(clip)))
    print("flashes:", detect_flash(clip))
    print("static:", find_static_scenes(clip))
    for line in export_edl(clip[:3]):
        print(line)
    for index, brightness in calculate_scene_brightness(clip):
        print("frame {:03d} brightness {:3d}".format(index, brightness))

