def perfect_scores(scores):
    positions = []
    for index, score in enumerate(scores):
        if score == 100:
            positions.append(index)
    return positions


def first_failing(scores):
    for index, score in enumerate(scores):
        if score is not None and score < 50:
            return index
    return -1


def points_milestone(scores, target=500):
    running = 0
    for index, score in enumerate(scores):
        running += score or 0
        if running >= target:
            return index
    return -1


def improvements(scores):
    marked = []
    for index, score in enumerate(scores):
        if index == 0 or score is None or scores[index - 1] is None:
            continue
        if score - scores[index - 1] > 20:
            marked.append(index)
    return marked


def exactly_passing(scores):
    return [index for index, score in enumerate(scores) if score == 50]


def gradebook(scores):
    lines = []
    passing = [(index, score) for index, score in enumerate(scores)
               if score is not None and score >= 50]
    for rank, (index, score) in enumerate(passing, start=1):
        lines.append("%d. student %d scored %d" % (rank, index, score))
    return lines


def absence_list(scores):
    absent = [index for index, score in enumerate(scores) if score is None]
    return ["%d) student %d was absent" % (number, index)
            for number, index in enumerate(absent, start=1)]


def transcript(scores):
    lines = []
    for question, score in enumerate(scores):
        shown = "absent" if score is None else str(score)
        lines.append("question %d: %s" % (question, shown))
    return lines


def grade(scores):
    for index, score in enumerate(scores):
        if score is not None and not 0 <= score <= 100:
            raise ValueError("invalid score %r at position %d" % (score, index))
    report = transcript(scores)
    report.extend(gradebook(scores))
    report.extend(absence_list(scores))
    report.append("perfect: %s" % perfect_scores(scores))
    report.append("first failing: %d" % first_failing(scores))
    report.append("500 points reached at: %d" % points_milestone(scores))
    report.append("improved: %s" % improvements(scores))
    report.append("borderline: %s" % exactly_passing(scores))
    return report


def main():
    sample = [40, 80, 100, None, 50, 95, 100, 70]
    for line in grade(sample):
        print(line)


if __name__ == "__main__":
    main()

