    for index in range(len(scores)):
        if index == 0 or scores[index] is None or scores[index - 1] is None:
            continue
        if scores[index] - scores[index - 1] > 20:
            marked.append(index)
    return marked


def exactly_passing(scores):
    return [index for index in range(len(scores)) if scores[index] == 50]


def gradebook(scores):
    lines = []
    passing = [(index, scores[index]) for index in range(len(scores))
               if scores[index] is not None and scores[index] >= 50]
    for rank in range(len(passing)):
        lines.append("%d. student %d scored %d" % (rank + 1, passing[rank][0], passing[rank][1]))
    return lines


def absence_list(scores):
    absent = [index for index in range(len(scores)) if scores[index] is None]
    return ["%d) student %d was absent" % (number + 1, absent[number])
            for number in range(len(absent))]


def transcript(scores):
    lines = []
    for question in range(len(scores)):
        shown = "absent" if scores[question] is None else str(scores[question])
        lines.append("question %d: %s" % (question, shown))
    return lines


def grade(scores):
    for index in range(len(scores)):
        if scores[index] is not None and not 0 <= scores[index] <= 100:
            raise ValueError("invalid score %r at position %d" % (scores[index], index))
    report = transcript(scores)
    report.extend(gradebook(scores))
    report.extend(absence_list(scores))
    report.append("perfect: %s" % perfect_scores(scores))
    report.append("first failing: %d" % first_failing(scores))
    report.append("500 points reached at: %d" % points_milestone(scores))
    report.append("improved: %s" % improvements(scores))
    report.append("borderline: %s" % exactly_passing(scores))
    return report


def main():
    sample = [40, 80, 100, None, 50, 95, 100, 70]
    for line in grade(sample):
        print(line)


if __name__ == "__main__":
    main()

