ANTIQUE_CUTOFF = 1900
MODERN_CUTOFF = 2020
AVERAGE_FLOOR = 1950
MILLENNIUM = 2000


def validate(years):
    clean = []
    for i, year in enumerate(years):
        if not isinstance(year, int) or isinstance(year, bool):
            raise TypeError("entry %d is not an integer year: %r" % (i, year))
        clean.append(year)
    return clean


def antique_positions(years):
    positions = []
    for i, year in enumerate(years):
        if year < ANTIQUE_CUTOFF:
            positions.append(i)
    return positions


def first_new_release(years):
    for i, year in enumerate(years):
        if year > MODERN_CUTOFF:
            return i
    return -1


def average_drop_index(years):
    total = 0
    for i, year in enumerate(years):
        total += year
        if total / (i + 1) < AVERAGE_FLOOR:
            return i
    return -1


def millennium_positions(years):
    return [i for i, year in enumerate(years) if year == MILLENNIUM]


def duplicate_runs(years):
    positions = []
    for i, year in enumerate(years):
        if i > 0 and year == years[i - 1]:
            positions.append(i)
    return positions


def shelf_list(years):
    lines = []
    slot = 0
    for i, year in enumerate(years):
        if year >= ANTIQUE_CUTOFF:
            slot += 1
            lines.append("Shelf %d: %d (index %d)" % (slot, year, i))
    return lines


def restoration_list(years, positions):
    tickets = []
    for ticket, position in enumerate(positions, start=1):
        tickets.append("Restoration %d: year %d at index %d" % (ticket, years[position], position))
    return tickets


def catalog_index(years):
    entries = []
    for index, year in enumerate(years):
        entries.append("%d -> %d" % (index, year))
    return entries


def audit(years):
    checked = validate(years)
    antiques = antique_positions(checked)
    shelves = shelf_list(checked)
    restorations = restoration_list(checked, antiques)
    for line, text in enumerate(shelves + restorations):
        print("%2d | %s" % (line, text))
    print("antiques=%s first_new=%d avg_drop=%d millennium=%s duplicates=%s" % (
        antiques, first_new_release(checked), average_drop_index(checked),
        millennium_positions(checked), duplicate_runs(checked)))
    return catalog_index(checked)


def main():
    samples = [[1990, 1850, 0], [1899, 1899, 2000, 2021, 1700]]
    for case, years in enumerate(samples, start=1):
        print("=== case %d ===" % case)
        for entry in audit(years):
            print(entry)


if __name__ == "__main__":
    main()

