SAMPLE_RATE = 8000
FADE_LENGTH = 100
PEAK_THRESHOLD = 50
ECHO_DELAY = 10
ECHO_GAIN = 0.5


def apply_fade_in(samples):
    faded = list(samples)
    for i, value in enumerate(faded[:FADE_LENGTH]):
        faded[i] = value * (i / FADE_LENGTH)
    return faded


def find_peaks(samples):
    peaks = []
    for i, value in enumerate(samples):
        if abs(value) > PEAK_THRESHOLD:
            peaks.append(i)
    return peaks


def downsample(samples):
    kept = []
    for i, value in enumerate(samples):
        if i % 2 == 0:
            kept.append(value)
    return kept


def lookahead_differences(samples):
    diffs = []
    for i, value in enumerate(samples):
        if i + 2 < len(samples):
            diffs.append(value - samples[i + 2])
    return diffs


def timestamp_samples(samples):
    stamped = []
    for i, value in enumerate(samples):
        stamped.append((value, i / SAMPLE_RATE))
    return stamped


def peak_report(samples):
    lines = []
    for i, value in enumerate(samples):
        if abs(value) > PEAK_THRESHOLD:
            lines.append("Peak of {:.2f} at index {} (t={:.4f}s)".format(value, i, i / SAMPLE_RATE))
    return lines


def apply_echo(samples):
    echoed = list(samples) + [0.0] * ECHO_DELAY
    for i, value in enumerate(samples):
        echoed[i + ECHO_DELAY] += value * ECHO_GAIN
    return echoed


def apply_fade_out(samples):
    faded = list(samples)
    start = max(0, len(faded) - FADE_LENGTH)
    span = len(faded) - start
    for offset, value in enumerate(faded[start:]):
        faded[start + offset] = value * (1 - (offset + 1) / span)
    return faded


def process(samples):
    faded_in = apply_fade_in(samples)
    peaks = find_peaks(samples)
    reduced = downsample(samples)
    diffs = lookahead_differences(samples)
    stamped = timestamp_samples(samples)
    report = peak_report(samples)
    echoed = apply_echo(samples)
    faded_out = apply_fade_out(samples)
    return (faded_in, peaks, reduced, diffs, stamped, report, echoed, faded_out)


def main():
    clip = [10, 60, 20, -75, 5, 90, 0, 30]
    results = process(clip)
    labels = ("fade-in", "peaks", "downsampled", "differences",
              "timestamps", "report", "echo", "fade-out")
    for n, label in enumerate(labels):
        print("{}. {}: {}".format(n + 1, label, results[n]))


if __name__ == "__main__":
    main()

