        faded[i] = faded[:FADE_LENGTH][i] * (i / FADE_LENGTH)
    return faded


def find_peaks(samples):
    peaks = []
    for i in range(len(samples)):
        if abs(samples[i]) > PEAK_THRESHOLD:
            peaks.append(i)
    return peaks


def downsample(samples):
    kept = []
    for i in range(len(samples)):
        if i % 2 == 0:
            kept.append(samples[i])
    return kept


def lookahead_differences(samples):
    diffs = []
    for i in range(len(samples)):
        if i + 2 < len(samples):
            diffs.append(samples[i] - samples[i + 2])
    return diffs


def timestamp_samples(samples):
    stamped = []
    for i in range(len(samples)):
        stamped.append((samples[i], i / SAMPLE_RATE))
    return stamped


def peak_report(samples):
    lines = []
    for i in range(len(samples)):
        if abs(samples[i]) > PEAK_THRESHOLD:
            lines.append("Peak of {:.2f} at index {} (t={:.4f}s)".format(samples[i], i, i / SAMPLE_RATE))
    return lines


def apply_echo(samples):
    echoed = list(samples) + [0.0] * ECHO_DELAY
    for i in range(len(samples)):
        echoed[i + ECHO_DELAY] += samples[i] * ECHO_GAIN
    return echoed


def apply_fade_out(samples):
    faded = list(samples)
    start = max(0, len(faded) - FADE_LENGTH)
    span = len(faded) - start
    for offset in range(len(faded[start:])):
        faded[start + offset] = faded[start:][offset] * (1 - (offset + 1) / span)
    return faded


def process(samples):
    faded_in = apply_fade_in(samples)
    peaks = find_peaks(samples)
    reduced = downsample(samples)
    diffs = lookahead_differences(samples)
    stamped = timestamp_samples(samples)
    report = peak_report(samples)
    echoed = apply_echo(samples)
    faded_out = apply_fade_out(samples)
    return (faded_in, peaks, reduced, diffs, stamped, report, echoed, faded_out)


def main():
    clip = [10, 60, 20, -75, 5, 90, 0, 30]
    results = process(clip)
    labels = ("fade-in", "peaks", "downsampled", "differences",
              "timestamps", "report", "echo", "fade-out")
    for n in range(len(labels)):
        print("{}. {}: {}".format(n + 1, labels[n], results[n]))


if __name__ == "__main__":
    main()

