def freezing_days(temperatures, freezing_point=32):
    days = []
    for index, temperature in enumerate(temperatures):
        if temperature < freezing_point:
            days.append(index + 1)
    return days


def cumulative_degree_days(temperatures):
    totals = []
    running = 0.0
    for index, temperature in enumerate(temperatures):
        running += temperature
        totals.append((index, round(running, 2)))
    return totals


def calibrated_temperatures(temperatures):
    calibrated = []
    for index, temperature in enumerate(temperatures):
        calibrated.append(round(temperature + (index + 1) / 10.0, 2))
    return calibrated


def local_peaks(temperatures):
    peaks = []
    last = len(temperatures) - 1
    for index, temperature in enumerate(temperatures):
        previous = temperatures[index - 1] if index > 0 else None
        following = temperatures[index + 1] if index < last else None
        higher_than_previous = previous is None or temperature > previous
        higher_than_following = following is None or temperature > following
        if higher_than_previous and higher_than_following:
            peaks.append((index, temperature))
    return peaks


def weather_reports(temperatures):
    reports = []
    for index, temperature in enumerate(temperatures):
        label = "freezing" if temperature < 32 else "above freezing"
        reports.append("Day {}: {} degrees ({})".format(index + 1, temperature, label))
    return reports


def shifted_forecast(temperatures, shift=2):
    forecast = [None] * len(temperatures)
    for index, temperature in enumerate(temperatures):
        target = index + shift
        if target < len(forecast):
            forecast[target] = temperature
    return forecast


def weekly_averages(temperatures, block=7):
    sums = []
    counts = []
    for index, temperature in enumerate(temperatures):
        week = index // block
        if week == len(sums):
            sums.append(0.0)
            counts.append(0)
        sums[week] += temperature
        counts[week] += 1
    return [round(total / counts[week], 2) for week, total in enumerate(sums)]


def hottest_day(temperatures):
    best_index = None
    best_temperature = None
    for index, temperature in enumerate(temperatures):
        if best_temperature is None or temperature > best_temperature:
            best_index = index
            best_temperature = temperature
    return best_index


def tabulate(temperatures):
    return (
        freezing_days(temperatures),
        cumulative_degree_days(temperatures),
        calibrated_temperatures(temperatures),
        local_peaks(temperatures),
        weather_reports(temperatures),
        shifted_forecast(temperatures),
        weekly_averages(temperatures),
        hottest_day(temperatures),
    )


def main():
    sample = [30, 40, 20, 35, 33, 31, 45, 28, 50]
    names = (
        "freezing days",
        "cumulative degree-days",
        "calibrated",
        "local peaks",
        "reports",
        "forecast",
        "weekly averages",
        "hottest day index",
    )
    results = tabulate(sample)
    for position, result in enumerate(results):
        print("{}. {}: {}".format(position + 1, names[position], result))


if __name__ == "__main__":
