        if 0 <= hour <= 6:
            adjusted.append(int(round(counts[hour] * factor)))
        else:
            adjusted.append(counts[hour])
    return adjusted


def traffic_spikes(counts):
    """Hour indices whose count is above both the preceding and following hour."""
    spikes = []
    for hour in range(len(counts)):
        if 0 < hour < len(counts) - 1 and counts[hour] > counts[hour - 1] and counts[hour] > counts[hour + 1]:
            spikes.append(hour)
    return spikes


def hourly_report(counts):
    """One formatted line per hour index."""
    lines = []
    for hour in range(len(counts)):
        lines.append("Hour %02d: %5d vehicles" % (hour, counts[hour]))
    return lines


def predict_next_day(counts):
    """Map each hour index shifted 24 hours forward to its expected count."""
    forecast = {}
    for hour in range(len(counts)):
        forecast[hour + 24] = counts[hour]
    return forecast


def group_into_blocks(counts, size=4):
    """Group counts into blocks of `size` hours, tagged with the block index."""
    blocks = []
    for hour in range(len(counts)):
        block_index = hour // size
        if block_index == len(blocks):
            blocks.append((block_index, []))
        blocks[block_index][1].append(counts[hour])
    return blocks


def quietest_hour(counts):
    """Hour index of the absolute lowest traffic, or None for no data."""
    best_hour = None
    for hour in range(len(counts)):
        if best_hour is None or counts[hour] < counts[best_hour]:
            best_hour = hour
    return best_hour


def monitor(counts):
    clean = validate_counts(counts)
    return (busy_hours(clean), cumulative_traffic(clean), apply_night_reduction(clean),
            traffic_spikes(clean), hourly_report(clean), predict_next_day(clean),
            group_into_blocks(clean), quietest_hour(clean))


def main():
    busy, totals, night, spikes, report, forecast, blocks, quiet = monitor([500, 1500, 800])
    print("busy hours:", busy, "spikes:", spikes, "quietest hour:", quiet)
    print("cumulative:", totals, "night-adjusted:", night)
    for line in report:
        print(line)
    for index in range(len(blocks)):
        block_index, values = blocks[index]
        print("block %d (position %d): %s" % (block_index, index, values))
    for hour in sorted(forecast):
        print("forecast hour %02d: %d vehicles" % (hour, forecast[hour]))


if __name__ == "__main__":
    main()

