    hours = []
    for hour, value in enumerate(usage):
        if value > threshold:
            hours.append(hour)
    return hours


def cumulative_totals(usage):
    totals = []
    running = 0.0
    for hour, value in enumerate(usage):
        running += value
        totals.append((hour, running))
    return totals


def tariff_charges(usage):
    return [value * hour for hour, value in enumerate(usage)]


def surge_hours(usage):
    hours = []
    for hour, value in enumerate(usage):
        if hour == 0 or hour == len(usage) - 1:
            continue
        if value > usage[hour - 1] and value > usage[hour + 1]:
            hours.append(hour)
    return hours


def energy_reports(usage):
    lines = []
    for hour, value in enumerate(usage):
        lines.append("Hour {:02d}: {:.1f} kWh".format(hour, value))
    return lines


def predictive_load(usage, shift=12):
    forecast = [0.0] * (len(usage) + shift)
    for hour, value in enumerate(usage):
        forecast[hour + shift] = value
    return forecast


def daily_blocks(usage, block=24):
    blocks = []
    for hour, value in enumerate(usage):
        day = hour // block
        if day == len(blocks):
            blocks.append([])
        blocks[day].append(value)
    return blocks


def lowest_hour(usage):
    best_hour = -1
    best_value = None
    for hour, value in enumerate(usage):
        if best_value is None or value < best_value:
            best_hour, best_value = hour, value
    return best_hour


