def pair_with_index(events):
    pairs = []
    for index, event in enumerate(events, start=1):
        pairs.append((event, index))
    return pairs


def map_to_hundreds(events):
    scaled = {}
    for index, event in enumerate(events, start=1):
        scaled[event] = index * 100
    return scaled


def prefix_with_index(events):
    labelled = []
    for index, event in enumerate(events, start=1):
        labelled.append("{}-{}".format(index, event))
    return labelled


def find_art_index(events):
    for index, event in enumerate(events, start=1):
        if "art" in event.lower():
            return index
    return None


def keep_odd_positions(events):
    return [event for index, event in enumerate(events, start=1) if index % 2 == 1]


def suffix_with_index(events):
    return ["{}:{}".format(event, index) for index, event in enumerate(events, start=1)]


def shortest_index(events):
    best_index = None
    best_length = None
    for index, event in enumerate(events, start=1):
        if best_length is None or len(event) < best_length:
            best_index = index
            best_length = len(event)
    return best_index


def index_to_event(events):
    catalogue = {}
    for index, event in enumerate(events, start=1):
        catalogue[index] = event
    return catalogue


def build(eras):
    if len(eras) != 8:
        raise ValueError("expected eight era lists, got {}".format(len(eras)))
    handlers = (
        pair_with_index,
        map_to_hundreds,
        prefix_with_index,
        find_art_index,
        keep_odd_positions,
        suffix_with_index,
        shortest_index,
        index_to_event,
    )
    results = []
    for position, handler in enumerate(handlers):
        results.append(handler(eras[position]))
    return tuple(results)


def report(names, outputs):
    lines = []
    for position, output in enumerate(outputs):
        lines.append("{}. {}: {!r}".format(position + 1, names[position], output))
    return "\n".join(lines)


def main():
    era_names = (
        "prehistory",
        "antiquity",
        "middle ages",
        "renaissance",
        "industrial age",
        "modern age",
        "contemporary age",
        "future",
    )
    eras = (
        ["cave paintings", "first tools", "fire mastered"],
        ["pyramids built", "Rome founded"],
        ["Magna Carta", "black death", "Gothic cathedrals"],
