    return [(day, views) for day, views in enumerate(counts)]


def peak_day(counts):
    best_day = None
    best_count = None
    for day, count in enumerate(counts):
        if best_count is None or count > best_count:
            best_day, best_count = day, count
    return best_day


def even_day_total(counts):
