CALIBRATION_FACTOR = 0.01
MAX_INDEX = 15
UNDERVOLT_LIMIT = 12.0
LABELS = ("A", "B", "C", "D", "E", "F", "G", "H")


def drift_correct(readings):
    corrected = []
    for index, voltage in enumerate(readings):
        corrected.append(voltage + index * CALIBRATION_FACTOR)
    return corrected


def first_undervolt_index(readings):
    for index, voltage in enumerate(readings):
        if voltage < UNDERVOLT_LIMIT:
            return index
    return -1


def expected_map(readings):
    table = {}
    for index, voltage in enumerate(readings):
        table[index] = float(voltage)
    return table


def trim_tail(readings):
    return [voltage for index, voltage in enumerate(readings) if index <= MAX_INDEX]


def log_lines(readings):
    return ["idx {0:03d}: {1:.3f} V".format(index, voltage)
            for index, voltage in enumerate(readings)]


def indexed_pairs(readings):
    return [(index, voltage) for index, voltage in enumerate(readings)]


def peak_index(readings):
    best = -1
    best_voltage = None
    for index, voltage in enumerate(readings):
        if best_voltage is None or voltage > best_voltage:
            best = index
            best_voltage = voltage
    return best


def odd_index_total(readings):
    total = 0.0
    for index, voltage in enumerate(readings):
        if index % 2:
            total += voltage
    return total


def calibrate(panels):
    a, b, c, d, e, f, g, h = panels
    return (drift_correct(a), first_undervolt_index(b), expected_map(c),
            trim_tail(d), log_lines(e), indexed_pairs(f), peak_index(g),
            odd_index_total(h))


def format_report(results):
    lines = []
    for position, output in enumerate(results):
        lines.append("Array {0} (#{1}) -> {2!r}".format(LABELS[position], position, output))
    return "\n".join(lines)


def main():
    panels = (
        [11.9, 12.1, 12.4],
        [13.0, 12.8, 11.4, 10.9],
        [12.0, 12.5],
        [12.2 + 0.1 * step for step in range(20)],
        [11.75, 12.05, 12.65],
        [12.3, 12.9],
        [11.2, 13.4, 12.8, 13.9, 13.1],
        [12.0, 11.5, 12.6, 13.2, 12.1],
    )
    for slot, readings in enumerate(panels):
        if not readings:
            raise ValueError("array {0} (#{1}) has no readings".format(LABELS[slot], slot))
    print(format_report(calibrate(panels)))


if __name__ == "__main__":
    main()

