REGION_NAMES = (
    "North", "South", "East", "West",
    "Central", "Coastal", "Valley", "Mountain",
)


def absentee_adjusted(counts):
    adjusted = []
    for index, count in enumerate(counts):
        adjusted.append(count + index)
    return adjusted


def first_index_above(counts, threshold=10000):
    for index, count in enumerate(counts):
        if count > threshold:
            return index
    return -1


def index_to_count_map(counts):
    mapping = {}
    for index, count in enumerate(counts):
        mapping[index] = count
    return mapping


def even_index_counts(counts):
    kept = []
    for index, count in enumerate(counts):
        if index % 2 == 0:
            kept.append(count)
    return kept


def official_record(counts):
    lines = []
    for index, count in enumerate(counts):
        lines.append("Record {:03d}: {} votes".format(index, count))
    return " | ".join(lines)


def indexed_pairs(counts):
    return [(index, count) for index, count in enumerate(counts)]


def index_of_maximum(counts):
    best_index = -1
    best_count = None
    for index, count in enumerate(counts):
        if best_count is None or count > best_count:
            best_index = index
            best_count = count
    return best_index


def prime_like_total(counts):
    total = 0
    for index, count in enumerate(counts):
        if index in PRIME_LIKE_INDICES:
            total += count
    return total


def tabulate(precincts):
    north, south, east, west, central, coastal, valley, mountain = precincts
    return (
        absentee_adjusted(north),
        first_index_above(south),
        index_to_count_map(east),
        even_index_counts(west),
        official_record(central),
        indexed_pairs(coastal),
        index_of_maximum(valley),
        prime_like_total(mountain),
    )


def certify(precincts):
    results = tabulate(precincts)
    report = []
    for position, certified in enumerate(results):
        report.append("{} -> {}".format(REGION_NAMES[position], certified))
    return "\n".join(report)


