    entries = []
    for order, guest in enumerate(interviews, start=1):
        entries.append({"kind": "interview", "detail": "guest {0}: {1}".format(order, guest)})
    return entries


def ad_slots(commercials):
    entries = []
    for slot, commercial in enumerate(commercials, start=1):
        entries.append({"kind": "commercial", "detail": "{0} in ad break slot {1}".format(commercial, slot)})
    return entries


BUILDERS = (number_days, label_sessions, channel_feeds, number_sets,
            game_sequence, reel_positions, guest_sequence, ad_slots)


def broadcast(event):
    if len(event) != len(BUILDERS):
        raise ValueError("event must contain exactly {0} sublists".format(len(BUILDERS)))
    schedule = []
    for items, build in zip(event, BUILDERS):
        schedule.extend(build(items))
    return schedule


def format_schedule(schedule):
    lines = []
    for line_no, entry in enumerate(schedule, start=1):
        lines.append("{0:2d}. {1:<11} {2}".format(line_no, entry["kind"], entry["detail"]))
    return lines


