def baseline_speeds(speeds):
    """Add each speed to its position in the original list."""
    return [speed + index for index, speed in enumerate(speeds)]


def qualify(sequence, threshold=50):
    """Keep only the speeds strictly above the threshold."""
    return [speed for speed in sequence if speed > threshold]


def weight(sequence):
    """Multiply each qualifying speed by its new index."""
    return [speed * index for index, speed in enumerate(sequence)]


def chunk(sequence, size=8):
    """Split the sequence into heats of at most `size` runners."""
    return [sequence[start:start + size] for start in range(0, len(sequence), size)]


def apply_lane_modifiers(heats):
    """Add the heat index and the lane index to every runner's speed."""
    adjusted = []
    for heat_index, heat in enumerate(heats):
        lanes = []
        for lane_index, speed in enumerate(heat):
            lanes.append(speed + heat_index + lane_index)
        adjusted.append(lanes)
    return adjusted


def team_bonuses(heats):
    """Sum speed * lane index across each heat."""
    bonuses = []
    for heat in heats:
        bonuses.append(sum(speed * lane_index for lane_index, speed in enumerate(heat)))
    return bonuses


def build_schedule(heats):
    """Describe every runner as 'Heat h, Lane l: speed'."""
    schedule = []
    for heat_index, heat in enumerate(heats):
        for lane_index, speed in enumerate(heat):
            schedule.append("Heat {}, Lane {}: {}".format(heat_index, lane_index, speed))
    return schedule


def allocate(speeds):
    for position, speed in enumerate(speeds):
        if not isinstance(speed, int) or isinstance(speed, bool):
            raise TypeError("speed at position {} is not an integer: {!r}".format(position, speed))
    heats = apply_lane_modifiers(chunk(weight(qualify(baseline_speeds(speeds)))))
    return build_schedule(heats)


def format_report(speeds):
    """Render the schedule together with the per-heat team bonuses."""
    heats = apply_lane_modifiers(chunk(weight(qualify(baseline_speeds(speeds)))))
    lines = list(build_schedule(heats))
    for heat_index, bonus in enumerate(team_bonuses(heats)):
        lines.append("Heat {} team bonus: {}".format(heat_index, bonus))
    return lines


def main():
    rosters = [[60, 40, 70], [55, 80, 49, 90, 51, 62, 73, 84, 95, 100]]
    for roster_index, roster in enumerate(rosters):
        print("Roster {}: {}".format(roster_index, roster))
        for line in format_report(roster):
            print("  " + line)
        print("  schedule entries: {}".format(len(allocate(roster))))


if __name__ == "__main__":
    main()

