def validate(counts):
    """Check that every entry is a usable page count."""
    if not isinstance(counts, list):
        raise TypeError("counts must be a list of integers")
    for index, count in enumerate(counts):
        if not isinstance(count, int) or isinstance(count, bool):
            raise TypeError("entry %d is not an integer: %r" % (index, count))
        if count < 0:
            raise ValueError("entry %d has a negative page count" % index)
    return counts


def base_sequence(counts):
    """Add each page count to its original position."""
    return [count + index for index, count in enumerate(counts)]


def keep_large(sequence):
    """Keep only the counts above one hundred."""
    return [count for count in sequence if count > 100]


def factored_sequence(sequence):
    """Multiply each surviving count by its new position."""
    return [count * index for index, count in enumerate(sequence)]


def make_shelves(sequence, size=10):
    """Split the sequence into shelves holding up to `size` books."""
    return [sequence[start:start + size] for start in range(0, len(sequence), size)]


def adjust_shelves(shelves):
    """Add the shelf index and the in-shelf position to every book count."""
    for shelf_index, shelf in enumerate(shelves):
        for book_index, count in enumerate(shelf):
            shelf[book_index] = count + shelf_index + book_index
    return shelves


def weight_bonus(shelves):
    """Sum each book count multiplied by its position on the shelf."""
    bonus = 0
    for shelf in shelves:
        for book_index, count in enumerate(shelf):
            bonus += count * book_index
    return bonus


def build_directory(shelves):
    """Describe every book as 'shelf/position/count'."""
    directory = []
    for shelf_index, shelf in enumerate(shelves):
        for book_index, count in enumerate(shelf):
            directory.append("shelf %d, book %d: %d pages" % (shelf_index, book_index, count))
    return directory


def organize(counts):
    validate(counts)
    shelves = make_shelves(factored_sequence(keep_large(base_sequence(counts))))
    adjust_shelves(shelves)
    weight_bonus(shelves)
    return build_directory(shelves)


def main():
    library = [150, 90, 110]
    directory = organize(library)
    shelves = make_shelves(factored_sequence(keep_large(base_sequence(library))))
    adjust_shelves(shelves)
    for line_number, entry in enumerate(directory, start=1):
        print("%2d. %s" % (line_number, entry))
    print("total weight bonus: %d" % weight_bonus(shelves))


if __name__ == "__main__":
    main()

