def validate(speeds):
    if not isinstance(speeds, list):
        raise TypeError("speeds must be a list of integers")
    for index, speed in enumerate(speeds):
        if not isinstance(speed, int) or isinstance(speed, bool):
            raise TypeError("speed at position %d is not an integer: %r" % (index, speed))
    return speeds


def baseline_sequence(speeds):
    return [speed + index for index, speed in enumerate(speeds)]


def filter_usable(baseline):
    return [speed for speed in baseline if speed > 12]


def weight_sequence(filtered):
    return [speed * position for position, speed in enumerate(filtered)]


def chunk_sectors(weighted, size=8):
    return [weighted[start:start + size] for start in range(0, len(weighted), size)]


def apply_wake(sectors):
    modified = []
    for sector_index, sector in enumerate(sectors):
        adjusted = []
        for unit_index, speed in enumerate(sector):
            adjusted.append(speed + sector_index + unit_index)
        modified.append(adjusted)
    return modified


def sector_bonuses(sectors):
    bonuses = []
    for sector in sectors:
        bonus = 0
        for unit_index, speed in enumerate(sector):
            bonus += speed * unit_index
        bonuses.append(bonus)
    return bonuses


def energy_report(sectors):
    report = []
    for sector_index, sector in enumerate(sectors):
        for unit_index, speed in enumerate(sector):
            report.append("Sector %d, Unit %d: %d" % (sector_index, unit_index, speed))
    return report


def build_sectors(speeds):
    validate(speeds)
    baseline = baseline_sequence(speeds)
    filtered = filter_usable(baseline)
    weighted = weight_sequence(filtered)
    return apply_wake(chunk_sectors(weighted))


def optimize(speeds):
    return energy_report(build_sectors(speeds))


def main():
    farms = {
        "north ridge": [15, 10, 20],
        "coastal": [3, 14, 18, 7, 25, 30, 11, 9, 22, 40],
        "calm valley": [1, 2, 3],
    }
