    if not isinstance(speeds, list):
        raise TypeError("speeds must be a list of integers")
    for index in range(len(speeds)):
        if not isinstance(speeds[index], int) or isinstance(speeds[index], bool):
            raise TypeError("speed at position %d is not an integer: %r" % (index, speeds[index]))
    return speeds


def baseline_sequence(speeds):
    return [speeds[index] + index for index in range(len(speeds))]


def filter_usable(baseline):
    return [speed for speed in baseline if speed > 12]


def weight_sequence(filtered):
    return [filtered[position] * position for position in range(len(filtered))]


def chunk_sectors(weighted, size=8):
    return [weighted[start:start + size] for start in range(0, len(weighted), size)]


def apply_wake(sectors):
    modified = []
    for sector_index in range(len(sectors)):
        adjusted = []
        for unit_index in range(len(sectors[sector_index])):
            adjusted.append(sectors[sector_index][unit_index] + sector_index + unit_index)
        modified.append(adjusted)
    return modified


def sector_bonuses(sectors):
    bonuses = []
    for sector in sectors:
        bonus = 0
        for unit_index in range(len(sector)):
            bonus += sector[unit_index] * unit_index
        bonuses.append(bonus)
    return bonuses


def energy_report(sectors):
    report = []
    for sector_index in range(len(sectors)):
        for unit_index in range(len(sectors[sector_index])):
            report.append("Sector %d, Unit %d: %d" % (sector_index, unit_index, sectors[sector_index][unit_index]))
    return report


def build_sectors(speeds):
    validate(speeds)
    baseline = baseline_sequence(speeds)
    filtered = filter_usable(baseline)
    weighted = weight_sequence(filtered)
    return apply_wake(chunk_sectors(weighted))


