JUMP_VALUES = {
    "toe_loop": 4.2,
    "salchow": 4.4,
    "loop": 4.9,
    "flip": 5.3,
    "lutz": 5.9,
    "triple_axel": 8.0,
    "quad_toe": 9.5,
}

SPIN_VALUES = {
    "upright_spin": 2.0,
    "sit_spin": 2.6,
    "camel_spin": 3.2,
    "flying_camel": 3.7,
}

HIGH_DIFFICULTY = {"triple_axel", "quad_toe", "lutz", "flying_camel"}

LATE_JUMP_BONUS = 0.10
SPIN_FOLLOW_UP_BONUS = 0.8


def normalize(routine):
    cleaned = []
    for idx, raw in enumerate(routine):
        if not isinstance(raw, str):
            raise TypeError("element %d is not a string: %r" % (idx + 1, raw))
        name = raw.strip().lower()
        if not name:
            raise ValueError("element %d is empty" % (idx + 1))
        cleaned.append(name)
    return cleaned


def classify(elements):
    jumps, spins = [], []
    for position, name in enumerate(elements):
        if name in JUMP_VALUES:
            jumps.append((position, name))
        elif name in SPIN_VALUES:
            spins.append((position, name))
        else:
            raise ValueError("unknown element %d: %s" % (position + 1, name))
    return jumps, spins


def score_jumps(jumps, routine_length):
    midpoint = routine_length / 2.0
    scored = []
    for position, name in jumps:
        base = JUMP_VALUES[name]
        if position + 1 > midpoint:
            base *= 1.0 + LATE_JUMP_BONUS
        scored.append((position, name, base))
    return scored


def score_spins(spins, elements):
    scored = []
    for position, name in spins:
        points = SPIN_VALUES[name]
        if position > 0 and elements[position - 1] in HIGH_DIFFICULTY:
            points += SPIN_FOLLOW_UP_BONUS
        scored.append((position, name, points))
    return scored


def collect_points(routine_length, *scored_groups):
    points = [0.0] * routine_length
    for group in scored_groups:
        for position, _, awarded in group:
            points[position] = awarded
    return points


def build_log(elements, points):
    lines = []
    for position, name in enumerate(elements):
        lines.append("#%d %-13s %5.2f" % (position + 1, name, points[position]))
    return "\n".join(lines)


def find_best(points):
    best_index, best_value = -1, float("-inf")
    for position, awarded in enumerate(points):
        if awarded > best_value:
            best_index, best_value = position, awarded
    return best_index


def ranking(elements, points, limit=3):
    order = sorted(range(len(points)), key=lambda p: points[p], reverse=True)
    lines = []
    for rank, position in enumerate(order[:limit], start=1):
        lines.append("%d. %s (#%d) %.2f" % (rank, elements[position], position + 1, points[position]))
    return lines


def score(routine):
    elements = normalize(routine)
    jumps, spins = classify(elements)
    points = collect_points(len(elements), score_jumps(jumps, len(elements)),
                            score_spins(spins, elements))
    log = build_log(elements, points)
    best = find_best(points)
    if best >= 0:
        log += "\nbest: %s (#%d)" % (elements[best], best + 1)
    return sum(points), log


def main():
    routines = [
        ["toe_loop", "sit_spin", "triple_axel", "camel_spin", "lutz", "flying_camel"],
        ["quad_toe", "upright_spin", "salchow", "loop"],
    ]
    for number, routine in enumerate(routines, start=1):
        total, log = score(routine)
        print("Routine %d - total %.2f" % (number, total))
        print(log)
        for line in ranking(normalize(routine), collect_points(
                len(routine),
                score_jumps(classify(normalize(routine))[0], len(routine)),
                score_spins(classify(normalize(routine))[1], normalize(routine)))):
            print("   " + line)


if __name__ == "__main__":
    main()

