def validate(books):
    if not isinstance(books, list):
        raise TypeError("books must be a list of thickness integers")
    for index, thickness in enumerate(books):
        if not isinstance(thickness, int) or isinstance(thickness, bool):
            raise TypeError("book %d has a non-integer thickness: %r" % (index, thickness))
        if thickness <= 0 or thickness > 50:
            raise ValueError("book %d has an unshelvable thickness: %d" % (index, thickness))


def pack_shelves(books, capacity=50):
    shelves = []
    current = []
    load = 0
    for index, thickness in enumerate(books):
        if current and load + thickness > capacity:
            shelves.append(current)
            current = []
            load = 0
        current.append((index, thickness))
        load += thickness
    if current:
        shelves.append(current)
    return shelves


def count_bookends(books, heavy=10):
    bookends = 0
    for index, thickness in enumerate(books[:-1]):
        if thickness > heavy and books[index + 1] <= heavy:
            bookends += 1
    return bookends


def widest_on_shelf(shelf):
    best_position = 0
    best_thickness = shelf[0][1]
    for position, (_, thickness) in enumerate(shelf):
        if thickness > best_thickness:
            best_position = position
            best_thickness = thickness
    return best_position, best_thickness


def build_manifests(shelves):
    manifests = []
    for number, shelf in enumerate(shelves, start=1):
        position, thickness = widest_on_shelf(shelf)
        manifests.append({
            "shelf": number,
            "books": [index for index, _ in shelf],
            "load": sum(width for _, width in shelf),
            "widest_position": position,
            "widest_index": shelf[position][0],
            "widest_thickness": thickness,
        })
    return manifests


def format_manifests(manifests, bookends):
    lines = []
    for entry in manifests:
        slots = []
        for slot, book_index in enumerate(entry["books"]):
            slots.append("slot %d -> book %d" % (slot, book_index))
        lines.append("Shelf %d (load %d/50): %s" % (entry["shelf"], entry["load"], ", ".join(slots)))
        lines.append("  widest: book %d, thickness %d, shelf position %d"
                     % (entry["widest_index"], entry["widest_thickness"], entry["widest_position"]))
    lines.append("Bookends needed: %d" % bookends)
    return lines


def organize(books):
    validate(books)
    shelves = pack_shelves(books)
    manifests = build_manifests(shelves)
    bookends = count_bookends(books)
    return manifests, bookends


def main():
    collection = [12, 4, 30, 8, 11, 6, 25, 20, 3, 14, 2, 18, 9, 7, 40]
    manifests, bookends = organize(collection)
    for line in format_manifests(manifests, bookends):
        print(line)


if __name__ == "__main__":
    main()

