            best_thickness = shelf[position][1]
    return best_position, best_thickness


def build_manifests(shelves):
    manifests = []
    for number in range(len(shelves)):
        position, thickness = widest_on_shelf(shelves[number])
        manifests.append({
            "shelf": number + 1,
            "books": [index for index, _ in shelves[number]],
            "load": sum(width for _, width in shelves[number]),
            "widest_position": position,
            "widest_index": shelves[number][position][0],
            "widest_thickness": thickness,
        })
    return manifests


def format_manifests(manifests, bookends):
    lines = []
    for entry in manifests:
        slots = []
        for slot in range(len(entry["books"])):
            slots.append("slot %d -> book %d" % (slot, entry["books"][slot]))
        lines.append("Shelf %d (load %d/50): %s" % (entry["shelf"], entry["load"], ", ".join(slots)))
        lines.append("  widest: book %d, thickness %d, shelf position %d"
                     % (entry["widest_index"], entry["widest_thickness"], entry["widest_position"]))
    lines.append("Bookends needed: %d" % bookends)
    return lines


def organize(books):
    validate(books)
    shelves = pack_shelves(books)
    manifests = build_manifests(shelves)
    bookends = count_bookends(books)
    return manifests, bookends


def main():
    collection = [12, 4, 30, 8, 11, 6, 25, 20, 3, 14, 2, 18, 9, 7, 40]
    manifests, bookends = organize(collection)
    for line in format_manifests(manifests, bookends):
        print(line)


