def has_duplicates(row):
    seen = set()
    for value in row:
        if value == 0:
            continue
        if value in seen:
            return True
        seen.add(value)
    return False


def find_invalid_rows(rows):
    invalid = []
    for index, row in enumerate(rows):
        if has_duplicates(row):
            invalid.append(index)
    return invalid


def missing_cells(row):
    missing = []
    for column, value in enumerate(row):
        if value == 0:
            missing.append(column)
    return missing


def collect_missing(rows):
    table = {}
    for index, row in enumerate(rows):
        table[index] = missing_cells(row)
    return table


def first_complete_row(rows):
    for index, row in enumerate(rows):
        if not missing_cells(row):
            return index
    return None


def describe_row(index, row, invalid_rows, missing):
    parts = ["row %d:" % index]
    if index in invalid_rows:
        parts.append("invalid (duplicate values)")
    elif missing:
