def grid_width(words):
    """Return the width of the widest answer, ignoring trailing blanks."""
    width = 0
    for index, word in enumerate(words):
        stripped = word.rstrip()
        if not stripped:
            raise ValueError("answer %d is empty" % (index + 1))
        if len(stripped) > width:
            width = len(stripped)
    return width


def pad_words(words, width):
    """Pair every answer with its clue number and pad it to the grid width."""
    numbered = []
    for position, word in enumerate(words, start=1):
        padded = word.rstrip().ljust(width)
        numbered.append((position, padded))
    return numbered


def find_intersections(numbered):
    """Letters that repeat the letter above them in the same column."""
    hits = []
    previous = None
    for row, (number, padded) in enumerate(numbered):
        if previous is not None:
            for column, letter in enumerate(padded):
                if letter != " " and letter == previous[column]:
                    hits.append((number, row, column, letter))
        previous = padded
    return hits


def format_log(numbered):
    """Build one log line per clue, pairing the number with the padded word."""
    log = []
    digits = len(str(len(numbered)))
    for line, (number, padded) in enumerate(numbered, start=1):
        log.append("%0*d across [%02d]: |%s|" % (digits, number, line, padded))
    return log


def populate(words):
    width = grid_width(words)
    numbered = pad_words(words, width)
    padded_words = [padded for _number, padded in numbered]
    log = format_log(numbered)
    for number, row, column, letter in find_intersections(numbered):
        log.append("clue %d crosses row %d at column %d on '%s'"
                   % (number, row, column, letter))
    return padded_words, log


def render_grid(padded_words):
    """Draw the grid with a column ruler so alignment can be checked."""
    width = len(padded_words[0]) if padded_words else 0
    lines = ["    " + "".join(str(c % 10) for c in range(width))]
    for row, padded in enumerate(padded_words):
        lines.append("%3d %s" % (row, padded.replace(" ", ".")))
    return "\n".join(lines)


def main():
    answers = ["parrot", "eagle", "ostrich", "owl", "swallow"]
    padded_words, log = populate(answers)
    print(render_grid(padded_words))
    print()
    for step, entry in enumerate(log, start=1):
        print("%2d. %s" % (step, entry))


if __name__ == "__main__":
    main()

YELLOW_DURATION = 3
RED_DURATION = 2
LONG_GREEN_THRESHOLD = 60


def green_phase_number(index):
    return index * 3 + 1


def validate_phases(phases):
    if not isinstance(phases, (list, tuple)):
        raise TypeError("phases must be a list of integers")
    checked = []
    for index, duration in enumerate(phases):
        if isinstance(duration, bool) or not isinstance(duration, int):
            raise TypeError("green duration at position %d is not an integer" % index)
        if duration <= 0:
            raise ValueError("green duration at position %d must be positive" % index)
        checked.append(duration)
    return checked


def build_timeline(greens):
    timeline = []
    for index, duration in enumerate(greens):
        number = green_phase_number(index)
        timeline.append((number, "green", duration))
        timeline.append((number + 1, "yellow", YELLOW_DURATION))
        timeline.append((number + 2, "red", RED_DURATION))
    return timeline


def pedestrian_priority_phases(greens):
    flagged = []
    for index, duration in enumerate(greens):
        if duration > LONG_GREEN_THRESHOLD:
            flagged.append(green_phase_number(index))
    return flagged


def format_timeline(timeline):
    lines = []
    elapsed = 0
    for step, (number, color, duration) in enumerate(timeline, start=1):
        lines.append(
            "step %2d | phase %2d | %-6s | %3ds | starts at %4ds"
            % (step, number, color, duration, elapsed)
        )
        elapsed += duration
    return lines


def simulate(phases):
    greens = validate_phases(phases)
    timeline = build_timeline(greens)
    total = sum(duration for _, _, duration in timeline)
    return total, timeline


def report(phases):
    total, timeline = simulate(phases)
    lines = format_timeline(timeline)
    lines.append("total cycle time: %ds" % total)
    flagged = pedestrian_priority_phases(validate_phases(phases))
    if flagged:
        for rank, number in enumerate(flagged, start=1):
            lines.append("pedestrian priority #%d: phase %d" % (rank, number))
    else:
        lines.append("pedestrian priority: none")
    return lines


def main():
    junctions = [[30, 45, 20], [75, 40, 90, 15], [60]]
    for position, phases in enumerate(junctions, start=1):
        print("Junction %d: greens %s" % (position, phases))
        for line in report(phases):
            print("  " + line)
        print()


if __name__ == "__main__":
    main()

