FAST_LIMIT = 10
MASSIVE_LIMIT = 100
COOLING_PAGES = 5


def validate(jobs):
    for submission, pages in enumerate(jobs, start=1):
        if not isinstance(pages, int) or isinstance(pages, bool):
            raise TypeError("job %d: page count must be an integer" % submission)
        if pages <= 0:
            raise ValueError("job %d: page count must be positive" % submission)


def split_tracks(jobs):
    fast, bulk = [], []
    for submission, pages in enumerate(jobs, start=1):
        if pages < FAST_LIMIT:
            fast.append((submission, pages))
        else:
            bulk.append((submission, pages))
    return fast, bulk


def insert_cooling(sequence):
    cooled = []
    final = len(sequence) - 1
    for position, (submission, pages) in enumerate(sequence):
        cooled.append((submission, pages))
        if pages > MASSIVE_LIMIT and position < final:
            cooled.append(("cool-%s" % submission, COOLING_PAGES))
    return cooled


def estimate_completion(sequence):
    timed = []
    for position, (submission, pages) in enumerate(sequence):
        preceding = sum(earlier for _, earlier in sequence[:position])
        timed.append((submission, pages, preceding + pages))
    return timed


def build_schedule(timed):
    schedule = []
    for slot, (submission, pages, completion) in enumerate(timed, start=1):
        schedule.append({"slot": slot, "submission": submission,
                         "pages": pages, "completion": completion})
    return schedule


def format_tracks(tracks):
    lines = []
    for rank, (name, track) in enumerate(tracks, start=1):
        lines.append("%d. %s track (%d entries)" % (rank, name, len(track)))
        for submission, pages in track:
            lines.append("     job %s -> %d pages" % (submission, pages))
    return lines


def optimize(jobs):
    validate(jobs)
    fast, bulk = split_tracks(jobs)
    bulk = insert_cooling(bulk)
    schedule = build_schedule(estimate_completion(fast + bulk))
    return fast, bulk, schedule


def main():
    fast, bulk, schedule = optimize([4, 120, 9, 45, 150, 2, 30])
    for line in format_tracks([("fast", fast), ("bulk", bulk)]):
        print(line)
    print("slot  submission  completion")
    for row in schedule:
        print("%4d  %10s  %10d" % (row["slot"], row["submission"], row["completion"]))
    print("queue drains after %d page-units" % schedule[-1]["completion"])


if __name__ == "__main__":
    main()

