            raise TypeError(f"swing at position {position} is not an integer: {arc!r}")
    return swings


def wide_arcs(swings):
    return {position: arc for position, arc in enumerate(swings) if arc > 20}


def first_weaker_index(swings):
    for position, arc in enumerate(swings):
        if position and arc < swings[position - 1]:
            return position
    return -1


def describe_swings(swings):
    return [f"Swing {position}: {arc} degrees" for position, arc in enumerate(swings)]


def interference_score(swings):
    score = 0
    for position, arc in enumerate(swings):
        if position:
            score += abs(arc - swings[position - 1])
    return score


