    pairs = []
    for position, arc in enumerate(swings):
        if position + 3 < len(swings):
            pairs.append((arc, swings[position + 3]))
    return pairs


def velocity_estimate(swings):
    return sum(arc * position for position, arc in enumerate(swings) if position % 2 == 0)


def weakest_index(swings):
    best = -1
    for position, arc in enumerate(swings):
        if best < 0 or arc < swings[best]:
