def tokenize(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    words = []
    current = []
    for char in text:
        if char.isalnum() or (char == "'" and current):
            current.append(char.lower())
        elif current:
            words.append("".join(current))
            current = []
    if current:
        words.append("".join(current))
    return [word.strip("'") for word in words if word.strip("'")]


def word_frequency(text):
    counts = {}
    for word in tokenize(text):
        counts[word] = counts.get(word, 0) + 1
    return counts


def first_occurrences(text):
    positions = {}
    for position, word in enumerate(tokenize(text)):
        positions.setdefault(word, position)
    return positions


def split_sentences(text):
    sentences = []
    current = []
    for char in text:
        current.append(char)
        if char in ".!?":
            sentences.append("".join(current))
            current = []
    tail = "".join(current).strip()
    if tail:
        sentences.append(tail)
    return sentences


def sentence_positions(text):
    positions = {}
    for number, sentence in enumerate(split_sentences(text), start=1):
        for word in tokenize(sentence):
            positions.setdefault(word, number)
    return positions


def rank_words(counts, first_seen):
    last = len(first_seen)
    ordered = sorted(counts.items(), key=lambda item: (-item[1], first_seen.get(item[0], last)))
    ranked = []
    previous_count = None
    rank = 0
    for offset, (word, count) in enumerate(ordered):
        if count != previous_count:
            rank = offset + 1
            previous_count = count
        ranked.append((rank, word, count))
    return ranked


def format_report(ranked):
    if not ranked:
        return "no words found"
    width = max(len(word) for _, word, _ in ranked)
    return "\n".join(
        "{:>3}. {:<{w}}  {}".format(rank, word, count, w=width) for rank, word, count in ranked
    )


def compare_texts(texts):
    totals = {}
    for source_id, text in enumerate(texts, start=1):
        for word, count in word_frequency(text).items():
            totals.setdefault(word, {})[source_id] = count
    return {word: sum(found.values()) for word, found in totals.items() if len(found) == len(texts)}


def main():
    samples = [
        "Hello world, hello Python!",
        "Python is great; the world of Python is wide. Python wins.",
    ]
    for number, sample in enumerate(samples, start=1):
        ranked = rank_words(word_frequency(sample), first_occurrences(sample))
        sentences = sentence_positions(sample)
        print("Text {}: {}".format(number, sample))
        print(format_report(ranked[:3]))
        for _, word, _ in ranked[:3]:
            print("  {} first appears in sentence {}".format(word, sentences[word]))
        print()
    combined = " ".join(samples)
    print("Words common to all texts:")
    print(format_report(rank_words(compare_texts(samples), first_occurrences(combined))))
    print()
    print("Combined vocabulary size:", len(word_frequency(combined)))


