ABSOLUTE_ZERO_C = -273.15


def celsius_to_fahrenheit(celsius):
    """Convert a Celsius temperature to Fahrenheit."""
    return celsius * 9 / 5 + 32


def parse_readings(raw_values):
    """Turn raw text readings into floats, reporting the offending position."""
    readings = []
    for index, raw in enumerate(raw_values):
        try:
            readings.append(float(raw))
        except (TypeError, ValueError):
            raise ValueError("reading %d is not a number: %r" % (index + 1, raw))
    return readings


def split_valid(readings):
    """Separate physically possible readings from those below absolute zero."""
    valid = []
    rejected = []
    for index, celsius in enumerate(readings):
        if celsius < ABSOLUTE_ZERO_C:
            rejected.append((index, celsius))
        else:
            valid.append(celsius)
    return valid, rejected


def format_table(readings):
    """Build a numbered conversion table as a list of text lines."""
    lines = ["  #  Celsius  Fahrenheit"]
    for index, celsius in enumerate(readings):
        lines.append("%3d %8.2f %11.2f" % (index + 1, celsius, celsius_to_fahrenheit(celsius)))
    return lines


def hottest(readings):
    """Return the index of the warmest reading, or None for empty input."""
    best_index = None
    for index, celsius in enumerate(readings):
        if best_index is None or celsius > readings[best_index]:
            best_index = index
    return best_index


def largest_jump(readings):
    """Return (index, delta) for the biggest change between consecutive readings."""
    best = None
    for index, celsius in enumerate(readings):
        if index == 0:
            continue
        delta = celsius - readings[index - 1]
        if best is None or abs(delta) > abs(best[1]):
            best = (index, delta)
    return best


def summarize(readings):
    lines = format_table(readings)
    peak = hottest(readings)
    if peak is not None:
        lines.append(
            "warmest: reading %d at %.2f C (%.2f F)"
            % (peak + 1, readings[peak], celsius_to_fahrenheit(readings[peak]))
        )
    jump = largest_jump(readings)
    if jump is not None:
        lines.append(
            "biggest change: reading %d shifted by %.2f C (%.2f F)"
            % (jump[0] + 1, jump[1], jump[1] * 9 / 5)
        )
    return lines


def main():
    raw_values = ["0", "25", "-40", "100", "36.6", "-300"]
    readings = parse_readings(raw_values)
    valid, rejected = split_valid(readings)
    for index, celsius in rejected:
        print("dropping reading %d (%.2f C): below absolute zero" % (index + 1, celsius))
    for line in summarize(valid):
        print(line)


if __name__ == "__main__":
    main()

