def validate_lists(*lists):
    """Check that every argument really is a list before comparing them."""
    for position, candidate in enumerate(lists, 1):
        if not isinstance(candidate, list):
            raise TypeError(
                "argument %d must be a list, got %s" % (position, type(candidate).__name__)
            )


def first_positions(values):
    """Map each hashable value to the index where it first appears."""
    positions = {}
    for index, value in enumerate(values):
        if value not in positions:
            positions[value] = index
    return positions


def list_intersection(list1, list2):
    """Return the common elements of two lists, in the order of list1, without repeats."""
    validate_lists(list1, list2)
