import string

ALPHABET_SIZE = 26
LOWER = string.ascii_lowercase


def _validated_shift(shift):
    if isinstance(shift, bool) or not isinstance(shift, int):
        raise TypeError("shift must be an integer")
    return shift % ALPHABET_SIZE


def _translation_table(shift):
    table = {}
    for index, letter in enumerate(LOWER):
        target = LOWER[(index + shift) % ALPHABET_SIZE]
        table[letter] = target
        table[letter.upper()] = target.upper()
    return table


def caesar_cipher_encrypt(text, shift):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    table = _translation_table(_validated_shift(shift))
    return "".join(table.get(ch, ch) for ch in text)


def caesar_cipher_decrypt(text, shift):
    return caesar_cipher_encrypt(text, -_validated_shift(shift))


def mapping_rows(text, shift):
    rows = []
    for index, (plain, coded) in enumerate(zip(text, caesar_cipher_encrypt(text, shift))):
        rows.append("pos {:>3}  {!r} -> {!r}".format(index, plain, coded))
    return rows


def alphabet_mapping(shift):
    table = _translation_table(_validated_shift(shift))
    return " ".join("{}{}".format(letter, table[letter]) for letter in LOWER)


def brute_force_decrypt(text):
    return [caesar_cipher_decrypt(text, candidate) for candidate in range(ALPHABET_SIZE)]


def format_report(text, shift):
    lines = [
        "text     : {!r}".format(text),
        "shift    : {}".format(_validated_shift(shift)),
        "cipher   : {!r}".format(caesar_cipher_encrypt(text, shift)),
        "alphabet : {}".format(alphabet_mapping(shift)),
    ]
    for number, row in enumerate(mapping_rows(text, shift), start=1):
        lines.append("  {:>2}. {}".format(number, row))
    details = ", ".join(
        "{}:{!r}".format(index, ch) for index, ch in enumerate(text) if not ch.isalpha()
    )
    if details:
        lines.append("  untouched -> " + details)
    return "\n".join(lines)


def main():
    samples = [("abc", 1), ("xyz", 3), ("Hello, World!", 5)]
    for case_number, (text, shift) in enumerate(samples, start=1):
        print("case {}".format(case_number))
        print(format_report(text, shift))
        print()

    secret = caesar_cipher_encrypt("Attack at dawn", 7)
    print("brute force of {!r}:".format(secret))
    for shift, candidate in enumerate(brute_force_decrypt(secret)):
        print("  shift {:>2} -> {}".format(shift, candidate))


if __name__ == "__main__":
    main()

