def update_inventory(inventory, item_name, quantity):
    if item_name in inventory:
        inventory[item_name] += quantity
    else:
        inventory[item_name] = quantity
    return inventory


def parse_transactions(lines):
    transactions = []
    for number, line in enumerate(lines, start=1):
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        parts = text.split()
        if len(parts) != 2:
            raise ValueError("line %d: cannot parse %r" % (number, text))
        name, raw_quantity = parts
        try:
            quantity = int(raw_quantity)
        except ValueError:
            raise ValueError("line %d: bad quantity %r" % (number, raw_quantity))
        transactions.append((name, quantity))
    return transactions


def find_shortages(transactions):
    projected = {}
    shortages = []
    for step, (name, quantity) in enumerate(transactions, start=1):
        update_inventory(projected, name, quantity)
        if projected[name] < 0:
            shortages.append((step, name, projected[name]))
    return shortages


def apply_transactions(inventory, transactions):
    history = []
    for step, (name, quantity) in enumerate(transactions, start=1):
        update_inventory(inventory, name, quantity)
        history.append((step, name, quantity, inventory[name]))
    return history


def format_shortages(shortages):
    lines = []
    for index, (step, name, level) in enumerate(shortages, start=1):
        lines.append("warning %d: step %d leaves %s at %d" % (index, step, name, level))
    return lines


def format_history(history):
    return ["%d. %s %+d -> %d" % record for record in history]


def format_inventory(inventory):
    names = sorted(inventory)
    width = max((len(name) for name in names), default=0)
    lines = []
    for position, name in enumerate(names, start=1):
        lines.append("%2d) %-*s %5d" % (position, width, name, inventory[name]))
    return lines


def format_ranking(inventory, limit):
    ranked = sorted(inventory.items(), key=lambda pair: (-pair[1], pair[0]))[:limit]
    lines = []
    for rank, (name, level) in enumerate(ranked, start=1):
        lines.append("%d. %s (%d)" % (rank, name, level))
    return lines


def main():
    raw = [
        "apple 10",
        "# restock",
        "banana 3",
        "apple 5",
        "cherry 12",
        "banana -5",
    ]
    transactions = parse_transactions(raw)
    for line in format_shortages(find_shortages(transactions)):
        print(line)
    inventory = {}
    history = apply_transactions(inventory, transactions)
    print("Transaction log:")
    for line in format_history(history):
        print("  " + line)
    print("Final inventory:")
    for line in format_inventory(inventory):
        print("  " + line)
    print("Best stocked:")
    for line in format_ranking(inventory, 2):
        print("  " + line)


if __name__ == "__main__":
    main()

