import math


def distance_2d(x1, y1, x2, y2):
    dx = x2 - x1
    dy = y2 - y1
    return math.sqrt(dx * dx + dy * dy)


def path_length(points):
    total = 0.0
    for index, (qx, qy) in enumerate(points[1:]):
        px, py = points[index]
        total += distance_2d(px, py, qx, qy)
    return total


def segment_report(points):
    lines = []
    for index, point in enumerate(points[1:]):
        start = points[index]
        length = distance_2d(start[0], start[1], point[0], point[1])
        lines.append("segment {}: {} -> {} = {:.3f}".format(
            index + 1, start, point, length))
    return lines


def nearest_pair(points):
    best = None
    best_gap = None
    for i, (ax, ay) in enumerate(points):
        for offset, (bx, by) in enumerate(points[i + 1:]):
            gap = distance_2d(ax, ay, bx, by)
            if best_gap is None or gap < best_gap:
                best_gap = gap
                best = (i, i + 1 + offset)
    return best, best_gap


def distance_matrix(points):
    matrix = []
    for ax, ay in points:
        matrix.append([distance_2d(ax, ay, bx, by) for bx, by in points])
    return matrix


def format_matrix(matrix, labels):
    rows = ["      " + " ".join("{:>7}".format(name) for name in labels)]
    for index, row in enumerate(matrix):
        cells = " ".join("{:7.3f}".format(value) for value in row)
        rows.append("{:>5} {}".format(labels[index], cells))
    return rows


def main():
    points = [(0, 0), (3, 4), (3, 5), (7, 8), (7, 8.5)]
    labels = []
    for index, point in enumerate(points):
        labels.append("P{}".format(index))
        print("P{} = {}".format(index, point))

    print("distance_2d(0, 0, 3, 4) =", distance_2d(0, 0, 3, 4))
    print("distance_2d(1, 1, 1, 1) =", distance_2d(1, 1, 1, 1))

    for line in segment_report(points):
        print(line)
    print("total path length = {:.3f}".format(path_length(points)))

    (first, second), gap = nearest_pair(points)
    print("closest pair: {} and {} at {:.3f}".format(
        labels[first], labels[second], gap))

    for line in format_matrix(distance_matrix(points), labels):
        print(line)


if __name__ == "__main__":
    main()

def parse_csv_line(line):
    """Split a single CSV line into its comma-separated values."""
    values = []
    start = 0
    for index, char in enumerate(line):
        if char == ',':
            values.append(line[start:index])
            start = index + 1
    values.append(line[start:])
    return values


def parse_csv_text(text):
    """Parse a multi-line CSV document into a list of field lists."""
    rows = []
    for raw in text.splitlines():
        stripped = raw.strip()
        if stripped:
            rows.append(parse_csv_line(stripped))
    return rows


def check_row_widths(rows):
    """Report rows whose field count differs from the header's."""
    if not rows:
        return []
    width = len(rows[0])
    problems = []
    for index, fields in enumerate(rows):
        if len(fields) != width:
            problems.append(
                'row %d: expected %d fields, found %d'
                % (index, width, len(fields))
            )
    return problems


def build_records(rows):
    """Turn header + data rows into dictionaries; rows must share a width."""
    header = rows[0]
    records = []
    for fields in rows[1:]:
        record = {}
        for column, name in enumerate(header):
            record[name] = fields[column]
        records.append(record)
    return records


def column_widths(header, records):
    widths = [len(name) for name in header]
    for record in records:
        for column, name in enumerate(header):
            widths[column] = max(widths[column], len(record[name]))
    return widths


def format_table(header, records):
    widths = column_widths(header, records)
    lines = []
    cells = [name.ljust(widths[column]) for column, name in enumerate(header)]
    lines.append(' | '.join(cells))
    lines.append('-+-'.join('-' * w for w in widths))
    for record in records:
        cells = []
        for column, name in enumerate(header):
            cells.append(record[name].ljust(widths[column]))
        lines.append(' | '.join(cells))
    return '\n'.join(lines)


def main():
    text = """fruit,count,origin
apple,12,Spain
banana,4,Ecuador
cherry,130,Turkey
"""
    rows = parse_csv_text(text)
    problems = check_row_widths(rows)
    if problems:
        for message in problems:
            print('warning: %s' % message)
        return
    records = build_records(rows)
    print(format_table(rows[0], records))


if __name__ == '__main__':
    main()

