    """Describe the reduction of n down to its digital root."""
    steps = digit_sum_chain(n)
    labels = []
    for step in range(len(steps)):
        labels.append("s%d=%d" % (step + 1, steps[step]))
    return ", ".join(labels)


def digital_root(n):
    chain = digit_sum_chain(n)
    return chain[-1] if chain else n


def build_table(numbers):
    """Build the table rows describing each number's digit sum."""
    rows = [["#", "n", "digit sum", "places", "reduction", "root"]]
    for index in range(len(numbers)):
        rows.append([str(index + 1), str(numbers[index]), str(sum_digits(numbers[index])),
                     format_breakdown(numbers[index]), format_chain(numbers[index]),
                     str(digital_root(numbers[index]))])
    return rows


def main(argv):
    text = " ".join(argv[1:]) if len(argv) > 1 else "123 9 4096 999999 0"
    try:
        numbers = parse_numbers(text)
    except ValueError as exc:
        print("input error: %s" % exc)
        return 1
    rows = build_table(numbers)
    widths = column_widths(rows)
    for row in rows:
        print(format_row(row, widths))
    print("total of all digit sums: %d" % sum(sum_digits(n) for n in numbers))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

