def validate_holdings(stocks, prices):
    """Check that every holding is well formed and priced; raise otherwise."""
    tickers = sorted(stocks, key=str)
    for index, ticker in enumerate(tickers):
        quantity = stocks[ticker]
        if not isinstance(ticker, str) or not ticker.strip():
            raise ValueError("holding %d: ticker must be a non-empty string" % (index + 1))
        if isinstance(quantity, bool) or not isinstance(quantity, (int, float)):
            raise ValueError("holding %d (%s): quantity must be numeric" % (index + 1, ticker))
        if quantity < 0:
            raise ValueError("holding %d (%s): quantity must not be negative" % (index + 1, ticker))
        if ticker not in prices:
            raise KeyError("holding %d (%s): no price available" % (index + 1, ticker))


def portfolio_value(stocks, prices):
    """Total market value of the holdings in `stocks` priced with `prices`."""
    validate_holdings(stocks, prices)
    total = 0
    for ticker, quantity in stocks.items():
        total += quantity * prices[ticker]
    return total


def holdings_breakdown(stocks, prices):
    """Per-ticker rows of (ticker, quantity, price, value), largest value first."""
    validate_holdings(stocks, prices)
    rows = [(ticker, quantity, prices[ticker], quantity * prices[ticker])
            for ticker, quantity in stocks.items()]
    rows.sort(key=lambda row: (-row[3], row[0]))
    return rows


def format_report(stocks, prices):
    """Render an aligned table of positions plus a total line."""
    total = portfolio_value(stocks, prices)
    breakdown = holdings_breakdown(stocks, prices)
    table = [("#", "TICKER", "QTY", "PRICE", "VALUE", "WEIGHT")]
    for rank, position in enumerate(breakdown):
        ticker, quantity, price, value = position
        weight = "%.1f%%" % (100.0 * value / total) if total else "-"
        table.append(("%d" % (rank + 1), ticker, "%g" % quantity, "%g" % price,
                      "%g" % value, weight))
    widths = [0] * len(table[0])
    for row in table:
        for column, cell in enumerate(row):
            widths[column] = max(widths[column], len(cell))
    lines = []
    for row in table:
        cells = [cell.ljust(widths[column]) for column, cell in enumerate(row)]
        lines.append("  ".join(cells).rstrip())
    if not breakdown:
        lines.append("(no positions)")
    lines.append("TOTAL: %g" % total)
    return "\n".join(lines)


def main():
    portfolios = [
        ("Core", {"AAPL": 10, "GOOG": 5}, {"AAPL": 150, "GOOG": 1000}),
        ("Empty", {}, {}),
        ("Mixed", {"MSFT": 3, "NVDA": 12, "KO": 40},
         {"MSFT": 410.5, "NVDA": 120, "KO": 62.25}),
        ("Broken", {"TSLA": -2}, {"TSLA": 250}),
    ]
    for number, portfolio in enumerate(portfolios):
        name, stocks, prices = portfolio
        print("%d. %s" % (number + 1, name))
        try:
            print(format_report(stocks, prices))
        except (ValueError, KeyError) as error:
            print("invalid portfolio: %s" % error)
        print()


if __name__ == "__main__":
    main()

