def scan_words(sentence):
    """Return [(word, start offset)] for every run of non-space characters."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a str, got %s" % type(sentence).__name__)
    found = []
    start = None
    for index, char in enumerate(sentence):
        if char.isspace():
            if start is not None:
                found.append((sentence[start:index], start))
                start = None
        elif start is None:
            start = index
    if start is not None:
        found.append((sentence[start:], start))
    return found


def index_map(found):
    """Pair every word with its offset, its old position and its new position."""
    last = len(found) - 1
    rows = []
    for index, (word, start) in enumerate(found):
        rows.append((word, start, index, last - index))
    return rows


def longest_word(found):
    """Return (word, position) for the longest word, earliest one on a tie."""
    best_word = ""
    best_index = -1
    for index, (word, _) in enumerate(found):
        if len(word) > len(best_word):
            best_word = word
            best_index = index
    return best_word, best_index


def reverse_words(sentence):
    """Reverse the order of the words in `sentence`, keeping each word intact."""
    return " ".join(word for word, _ in reversed(scan_words(sentence)))


def format_table(rows):
    """Render the position rows as numbered lines of fixed-width columns."""
    width = max((len(word) for word, _, _, _ in rows), default=4)
    lines = []
    for line_number, (word, start, old, new) in enumerate(rows, start=1):
        lines.append("{:>2}. {:<{w}}  offset {:>3}  {} -> {}".format(
            line_number, word, start, old, new, w=width))
    return lines


def describe(sentence):
    """Build a short human-readable report about reversing one sentence."""
    found = scan_words(sentence)
    report = ["input : " + sentence, "output: " + reverse_words(sentence)]
    word, position = longest_word(found)
    if word:
        report.append("longest: '%s' at original position %d" % (word, position))
    report.extend(format_table(index_map(found)))
    return report


def main():
    samples = [
        "hello world",
        "Python is fun",
        "  keep   the    characters intact  ",
        "single",
    ]
    for number, sample in enumerate(samples, start=1):
        print("=== sample %d ===" % number)
        for line in describe(sample):
            print(line)
        print()


if __name__ == "__main__":
    main()

