def validate_numbers(numbers):
    """Return the values as a list, or raise a descriptive error."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    for index, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(
                "element %d (%r) is not an int or float" % (index, value)
            )
    return list(numbers)


def first_zero_index(numbers):
    """Position of the first zero, or None when the product cannot vanish."""
    for index, value in enumerate(numbers):
        if value == 0:
            return index
    return None


def format_factors(numbers):
    """Render the multiplication as 'a * b * c = product'."""
    pieces = []
    for index, value in enumerate(numbers):
        text = str(value)
        if value < 0 and index:
            text = "(%s)" % text
        pieces.append(text)
    left = " * ".join(pieces) if pieces else "1"
    return "%s = %s" % (left, product_list(numbers))


def product_list(numbers):
    """Multiply every element of numbers together; empty list gives 1."""
    values = validate_numbers(numbers)
    product = 1
    for value in values:
        if value == 0:
            return 0
        product *= value
    return product


def running_products(numbers):
    """Prefix products: element i is the product of numbers[:i + 1]."""
    values = validate_numbers(numbers)
    partials = []
    product = 1
    for value in values:
        product *= value
        partials.append(product)
    return partials


