def validate_numbers(numbers):
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    checked = []
    for index, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("element %d is not an int: %r" % (index, value))
        checked.append(value)
    return checked


def filter_odd(numbers):
    values = validate_numbers(numbers)
    odd_numbers = []
    for value in values:
        if value % 2 != 0:
            odd_numbers.append(value)
    return odd_numbers


def odd_positions(numbers):
    values = validate_numbers(numbers)
    positions = {}
    for index, value in enumerate(values):
        if value % 2 != 0:
            positions.setdefault(value, []).append(index)
    return positions


def format_table(numbers):
    values = validate_numbers(numbers)
    lines = ["idx  value  parity"]
    for index, value in enumerate(values):
        parity = "odd" if value % 2 != 0 else "even"
        lines.append("%3d  %5d  %s" % (index, value, parity))
    return "\n".join(lines)


def summarize(numbers):
    odds = filter_odd(numbers)
    positions = odd_positions(numbers)
    parts = []
    for rank, value in enumerate(odds, start=1):
        where = ", ".join(str(p) for p in positions[value])
        parts.append("#%d: %d at [%s]" % (rank, value, where))
    if not parts:
        return "no odd numbers found"
    return "; ".join(parts)


def main():
    datasets = [
        [1, 2, 3, 4, 5],
        [2, 4, 6],
        [-7, 0, 7, 7, 12, 15],
    ]
    for case_number, data in enumerate(datasets, start=1):
        print("Case %d: input = %r" % (case_number, data))
        print(format_table(data))
        print("odd numbers:", filter_odd(data))
        print("summary:", summarize(data))
        print()

    try:
        filter_odd([1, "three", 5])
    except TypeError as error:
        print("rejected bad input:", error)


if __name__ == "__main__":
    main()

