def fahrenheit_to_celsius(fahrenheit):
    """Return the Celsius equivalent of a Fahrenheit temperature."""
    return (float(fahrenheit) - 32.0) * 5.0 / 9.0


def parse_readings(raw_values):
    """Turn a sequence of user-supplied values into floats.

    Values that cannot be read as numbers are reported with their position.
    """
    readings = []
    problems = []
    for index, raw in enumerate(raw_values):
        try:
            readings.append(float(str(raw).strip()))
        except ValueError:
            problems.append("value #%d (%r) is not a number" % (index + 1, raw))
    return readings, problems


def convert_all(readings):
    """Convert every Fahrenheit reading to Celsius, keeping the input order."""
    return [fahrenheit_to_celsius(value) for value in readings]


def label_extremes(celsius_values):
    """Map each index to 'coldest' / 'hottest' where those extremes occur."""
    if not celsius_values:
        return {}
    coldest = 0
    hottest = 0
    for index, value in enumerate(celsius_values):
        if value < celsius_values[coldest]:
            coldest = index
        if value > celsius_values[hottest]:
            hottest = index
    labels = {coldest: "coldest", hottest: "hottest"}
    return labels


def format_table(readings, celsius_values):
    """Build an aligned text table of the conversions."""
    labels = label_extremes(celsius_values)
    header = "%3s  %12s  %12s  %s" % ("#", "Fahrenheit", "Celsius", "note")
    lines = [header, "-" * len(header)]
    for index, fahrenheit in enumerate(readings):
        note = labels.get(index, "")
        lines.append("%3d  %12.2f  %12.2f  %s"
                     % (index + 1, fahrenheit, celsius_values[index], note))
    return "\n".join(lines)


def freezing_indices(celsius_values):
    """Positions (1-based) of readings at or below the freezing point."""
    positions = []
    for index, celsius in enumerate(celsius_values):
        if celsius <= 0.0:
            positions.append(index + 1)
    return positions


