def rectangle_area(width, height):
    """Return the area of a rectangle with the given width and height."""
    for name, value in (("width", width), ("height", height)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("%s must be a number, got %r" % (name, value))
        if value < 0:
            raise ValueError("%s must not be negative, got %r" % (name, value))
    return float(width) * float(height)


def parse_dimensions(text):
    """Parse lines of 'width height' into a list of (width, height) pairs."""
    pairs = []
    for lineno, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped:
            continue
        fields = stripped.replace(",", " ").split()
        if len(fields) != 2:
            raise ValueError("line %d: expected two values, got %d" % (lineno, len(fields)))
        numbers = []
        for position, field in enumerate(fields):
            try:
                numbers.append(float(field))
            except ValueError:
