def count_words(text):
    """Return the number of space-separated words in text."""
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %s" % type(text).__name__)
    return len(scan_words(text))


def scan_words(text):
    """Return a list of (offset, word) pairs for every word in text."""
    spans = []
    start = None
    for index, char in enumerate(text):
        if char == ' ':
            if start is not None:
                spans.append((start, text[start:index]))
                start = None
        elif start is None:
            start = index
    if start is not None:
        spans.append((start, text[start:]))
    return spans


def longest_index(spans):
    """Return the position of the longest word, earliest one on a tie."""
    best = 0
    for index, span in enumerate(spans):
        if len(span[1]) > len(spans[best][1]):
            best = index
    return best


def normalize(word):
    """Strip surrounding punctuation and fold case for comparisons."""
    return word.strip('.,;:!?"\'').lower()


def word_positions(spans):
    """Map each normalized word to the list of positions where it occurs."""
    positions = {}
    for index, span in enumerate(spans):
        positions.setdefault(normalize(span[1]), []).append(index)
    return positions


def repeated_words(spans):
    """Return (word, count, first position) for words used more than once."""
    positions = word_positions(spans)
    repeats = []
    for index, span in enumerate(spans):
        places = positions[normalize(span[1])]
        if len(places) > 1 and places[0] == index:
            repeats.append((normalize(span[1]), len(places), index))
    return repeats


def average_length(spans):
    """Return the mean length of the words in spans."""
    return sum(len(span[1]) for span in spans) / len(spans)


def format_report(text):
    """Build a human readable summary of the words found in text."""
    spans = scan_words(text)
    lines = ["text: %r" % text, "word count: %d" % count_words(text)]
    if not spans:
        lines.append("  (no words found)")
        return "\n".join(lines)
    best = longest_index(spans)
    for index, span in enumerate(spans):
        marker = "  <- longest" if index == best else ""
        lines.append("  %2d. offset %3d  %s%s" % (index + 1, span[0], span[1], marker))
    lines.append("average word length: %.2f" % average_length(spans))
    for word, count, first in repeated_words(spans):
        lines.append("  %r appears %d times, first as word %d" % (word, count, first + 1))
    return "\n".join(lines)


def main():
    samples = [
        'This is a test sentence.',
        '  Hello   world  ',
        '',
        'the cat sat on the mat and the cat purred',
    ]
    for index, sample in enumerate(samples):
        print("case %d" % (index + 1))
        print(format_report(sample))
        print()


if __name__ == '__main__':
    main()

