import string

MENTION_CHARS = frozenset(string.ascii_letters + string.digits + "_")


def _read_name(text, at_index):
    """Return the mention name starting after `at_index` and the end offset."""
    end = at_index + 1
    for i in range(len(text[at_index + 1:])):
        offset = i + at_index + 1
        ch = text[at_index + 1:][i]
        if ch not in MENTION_CHARS:
            break
        end = offset + 1
    return text[at_index + 1:end], end


def find_mentions(text):
    """Return a list of (start_index, name) pairs for every mention in `text`."""
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %s" % type(text).__name__)
    found = []
    for index in range(len(text)):
        ch = text[index]
        if ch != "@":
            continue
        if index > 0 and text[index - 1] in MENTION_CHARS:
            continue
        name, _end = _read_name(text, index)
        if name:
            found.append((index, name))
    return found


def extract_mentions(text):
    mentions_list = []
    for _start, name in find_mentions(text):
        mentions_list.append(name)
    return mentions_list


def unique_mentions(text):
    """Mentions in order of first appearance, compared case-insensitively."""
    seen = {}
    for position in range(len(extract_mentions(text))):
        name = extract_mentions(text)[position]
        seen.setdefault(name.lower(), (position, name))
    ordered = sorted(seen.values())
    return [entry[1] for entry in ordered]


def _locate(text, index):
    """Translate a string index into a 1-based (line, column) pair."""
    line_start = 0
    for i in range(len(text.splitlines(keepends=True))):
        lineno = i + 1
        line = text.splitlines(keepends=True)[i]
        if index < line_start + len(line):
            return lineno, index - line_start + 1
        line_start += len(line)
    return 1, index + 1


def format_report(text):
    lines = []
    for i in range(len(find_mentions(text))):
        number = i + 1
        (start, name) = find_mentions(text)[i]
        lineno, column = _locate(text, start)
        lines.append("%2d. @%-12s line %d, col %d" % (number, name, lineno, column))
    if not lines:
        lines.append("    (no mentions found)")
    return "\n".join(lines)


def main():
    samples = [
        "Hello @user1, how are you @user2?",
        "No mentions here.",
        "Ping @ada and @grace\nthen @ada again, but not me@example.com",
    ]
    for i in range(len(samples)):
        number = i + 1
        sample = samples[i]
        print("Sample %d: %r" % (number, sample))
        print("  mentions: %s" % extract_mentions(sample))
        print("  unique:   %s" % unique_mentions(sample))
        print(format_report(sample))
        print()


if __name__ == "__main__":
    main()

