import sys


def scan_text(text):
    """Return per-character counts and the index where each character first appears."""
    counts = {}
    first_seen = {}
    for index, char in enumerate(text):
        counts[char] = counts.get(char, 0) + 1
        if char not in first_seen:
            first_seen[char] = index
    return counts, first_seen


def least_frequent_char(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not text:
        raise ValueError("text must not be empty")
    counts, first_seen = scan_text(text)
    best_char = None
    best_key = None
    for char, count in counts.items():
        key = (count, first_seen[char])
        if best_key is None or key < best_key:
            best_char, best_key = char, key
    return best_char


def positions_of(text, target):
    """Return every index in text holding the target character."""
    return [index for index, char in enumerate(text) if char == target]


def frequency_rows(text):
    """Rank characters from rarest to most common, ties broken by first appearance."""
    counts, first_seen = scan_text(text)
    ordered = sorted(counts.items(), key=lambda item: (item[1], first_seen[item[0]]))
    rows = []
    for rank, (char, count) in enumerate(ordered, start=1):
        rows.append((str(rank), describe_char(char), str(count), str(first_seen[char])))
    return rows


def describe_char(char):
    if char == " ":
        return "' '"
    if char.isprintable():
        return char
    return repr(char).strip("'")


def format_table(headers, rows):
    widths = [len(header) for header in headers]
    for row in rows:
        for column, cell in enumerate(row):
            widths[column] = max(widths[column], len(cell))
    lines = ["  ".join(header.ljust(width) for header, width in zip(headers, widths))]
    lines.append("  ".join("-" * width for width in widths))
    for row in rows:
        lines.append("  ".join(cell.ljust(width) for cell, width in zip(row, widths)))
    return lines


def marker_line(text, indices):
    marker = [" "] * len(text)
    for index in indices:
        marker[index] = "^"
    return "".join(marker)


def main(argv):
    texts = argv[1:]
    if not texts:
        print("usage: {} TEXT [TEXT ...]".format(argv[0]), file=sys.stderr)
        return 1
    headers = ("rank", "char", "count", "first")
    for number, text in enumerate(texts, start=1):
        print("input {}: {!r}".format(number, text))
        try:
            rarest = least_frequent_char(text)
        except ValueError as error:
            print("  skipped: {}".format(error))
            continue
        for line in format_table(headers, frequency_rows(text)):
            print("  " + line)
        spots = positions_of(text, rarest)
        print("  " + text)
        print("  " + marker_line(text, spots))
        print("  least frequent -> {!r} at {}".format(rarest, spots))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

