        rows.append((str(rank + 1), describe_char(ordered[rank][0]), str(ordered[rank][1]), str(first_seen[ordered[rank][0]])))
    return rows


def describe_char(char):
    if char == " ":
        return "' '"
    if char.isprintable():
        return char
    return repr(char).strip("'")


def format_table(headers, rows):
    widths = [len(header) for header in headers]
    for row in rows:
        for column in range(len(row)):
            widths[column] = max(widths[column], len(row[column]))
    lines = ["  ".join(header.ljust(width) for header, width in zip(headers, widths))]
    lines.append("  ".join("-" * width for width in widths))
    for row in rows:
        lines.append("  ".join(cell.ljust(width) for cell, width in zip(row, widths)))
    return lines


def marker_line(text, indices):
    marker = [" "] * len(text)
    for index in indices:
        marker[index] = "^"
    return "".join(marker)


def main(argv):
    texts = argv[1:]
    if not texts:
        print("usage: {} TEXT [TEXT ...]".format(argv[0]), file=sys.stderr)
        return 1
    headers = ("rank", "char", "count", "first")
    for number in range(len(texts)):
        print("input {}: {!r}".format(number + 1, texts[number]))
        try:
            rarest = least_frequent_char(texts[number])
        except ValueError as error:
            print("  skipped: {}".format(error))
