        for line in format_table(headers, frequency_rows(texts[number])):
            print("  " + line)
        spots = positions_of(texts[number], rarest)
        print("  " + texts[number])
        print("  " + marker_line(texts[number], spots))
        print("  least frequent -> {!r} at {}".format(rarest, spots))
    return 0


