def validate_records(dict_list, key):
    """Return a list of error messages describing unusable records."""
    if not isinstance(dict_list, list):
        return ["input is not a list"]
    errors = []
    for index, record in enumerate(dict_list):
        if not isinstance(record, dict):
            errors.append("record %d is not a dict" % index)
        elif key not in record:
            errors.append("record %d is missing key %r" % (index, key))
    return errors


def sort_dicts_by_key(dict_list, key):
    """Return a new list with the dictionaries sorted by dict_list[i][key]."""
    errors = validate_records(dict_list, key)
    if errors:
        raise ValueError("; ".join(errors))
    return sorted(dict_list, key=lambda record: record[key])


def collect_columns(dict_list, key):
    """Return column names with the sort key first, then the remaining keys."""
    columns = [key]
    for record in dict_list:
        for name in record:
            if name not in columns:
                columns.append(name)
    return columns


def format_table(dict_list, columns):
    """Render the records as a fixed-width text table."""
    widths = [len(name) for name in columns]
    for record in dict_list:
        for position, name in enumerate(columns):
            widths[position] = max(widths[position], len(str(record.get(name, ""))))
    header = "  ".join(name.ljust(width) for name, width in zip(columns, widths))
    lines = [header, "  ".join("-" * width for width in widths)]
    for record in dict_list:
        cells = []
        for position, name in enumerate(columns):
            cells.append(str(record.get(name, "")).ljust(widths[position]))
        lines.append("  ".join(cells))
    return "\n".join(lines)


def report(dict_list, key):
    """Sort the records and describe the result as printable lines."""
    sorted_list = sort_dicts_by_key(dict_list, key)
    columns = collect_columns(sorted_list, key)
    lines = ["sorted %d record(s) by %r" % (len(sorted_list), key)]
    lines.append(format_table(sorted_list, columns))
    for rank, record in enumerate(sorted_list, start=1):
        lines.append("#%d -> %s" % (rank, record[key]))
    return lines


def main():
    datasets = [
        ([{'name': 'B', 'age': 30}, {'name': 'A', 'age': 20}], 'age'),
        ([{'id': 2}, {'id': 1}], 'id'),
        ([{'name': 'C'}, {'name': 'A', 'note': 'x'}, {'name': 'B'}], 'name'),
        ([{'name': 'D'}, {'age': 5}], 'name'),
    ]
    for number, (records, key) in enumerate(datasets, start=1):
        print("dataset %d:" % number)
        try:
            for line in report(records, key):
                print("   " + line)
        except ValueError as exc:
            print("   error: %s" % exc)


if __name__ == "__main__":
    main()

