import random
from collections import Counter

FACES = ('Heads', 'Tails')


def simulate_coin_flip():
    """Flip a fair coin once and return 'Heads' or 'Tails'."""
    result = random.choice(FACES)
    return result


def flip_many(count):
    """Return a list of `count` independent flip outcomes."""
    if count < 0:
        raise ValueError("count must be non-negative")
    return [simulate_coin_flip() for _ in range(count)]


def first_position(flips, face):
    """Return the 1-based position of the first `face`, or None if absent."""
    for position, value in enumerate(flips, start=1):
        if value == face:
            return position
    return None


def count_alternations(flips):
    """Count how often the outcome differs from the previous flip."""
    changes = 0
    for index, face in enumerate(flips[1:]):
        if face != flips[index]:
            changes += 1
    return changes


def longest_streak(flips):
    """Return (face, length) of the longest run of identical outcomes."""
    best_face, best_length = None, 0
    current_length = 0
    for index, face in enumerate(flips):
        if index > 0 and face == flips[index - 1]:
            current_length += 1
        else:
            current_length = 1
        if current_length > best_length:
            best_face, best_length = face, current_length
    return best_face, best_length


def format_sequence(flips, per_line=10):
    """Render flips as numbered rows of abbreviated outcomes."""
    lines = []
    row = []
    for index, face in enumerate(flips, start=1):
        row.append(face[0])
        if index % per_line == 0:
            lines.append("{:>4}: {}".format(index - len(row) + 1, " ".join(row)))
            row = []
    if row:
        lines.append("{:>4}: {}".format(len(flips) - len(row) + 1, " ".join(row)))
    return "\n".join(lines)


def format_report(flips):
    """Build a text report with per-face counts, shares and first positions."""
    total = len(flips)
    counts = Counter(flips)
    lines = ["Flips: {}".format(total)]
    for number, face in enumerate(FACES, start=1):
        amount = counts[face]
        share = amount / total * 100 if total else 0.0
        appeared = first_position(flips, face)
        lines.append("{}. {:<5} {:>4} ({:5.1f}%) first at {}".format(
            number, face, amount, share, appeared if appeared else "-"))
    face, length = longest_streak(flips)
    if face is not None:
        lines.append("Longest streak: {} x {}".format(length, face))
    lines.append("Changes of side: {}".format(count_alternations(flips)))
    return "\n".join(lines)


def main():
    random.seed()
    print("Single flip:", simulate_coin_flip())
    flips = flip_many(35)
    print(format_sequence(flips))
    print(format_report(flips))


if __name__ == "__main__":
    main()

