PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = set(PAIRS.values())


def validate(s):
    """Return a list of (index, character) for characters that are not brackets."""
    if not isinstance(s, str):
        raise TypeError("input must be a string")
    invalid = []
    for index, char in enumerate(s):
        if char not in OPENERS and char not in PAIRS:
            invalid.append((index, char))
    return invalid


def is_brackets_balanced(s):
    """Return True if every bracket in s is closed in the correct order."""
    stack = []
    for index, char in enumerate(s):
        if char in OPENERS:
            stack.append((index, char))
        elif char in PAIRS:
            if not stack or stack[-1][1] != PAIRS[char]:
                return False
            stack.pop()
    return not stack


def first_mismatch(s):
    """Return the index of the first bracket that breaks the nesting, or None."""
    stack = []
    for index, char in enumerate(s):
        if char in OPENERS:
            stack.append((index, char))
        elif char in PAIRS:
            if not stack or stack[-1][1] != PAIRS[char]:
                return index
            stack.pop()
    if stack:
        return stack[0][0]
    return None


def depth_profile(s):
    """Return the nesting depth after each character of s."""
    depths = []
    depth = 0
    for char in s:
        if char in OPENERS:
            depth += 1
        elif char in PAIRS:
            depth -= 1
        depths.append(depth)
    return depths


def describe(s):
    """Build a human readable report about the bracket string s."""
    lines = []
    invalid = validate(s)
    for position, (index, char) in enumerate(invalid, start=1):
        lines.append("  invalid #%d: %r at index %d" % (position, char, index))
    balanced = is_brackets_balanced(s)
    lines.append("  balanced: %s" % balanced)
    if not balanced:
        lines.append("  first problem at index %d" % first_mismatch(s))
    else:
        profile = depth_profile(s)
        deepest = max(profile) if profile else 0
        lines.append("  maximum nesting depth: %d" % deepest)
        for index, depth in enumerate(profile):
            if depth == deepest and s[index] in OPENERS:
                lines.append("  deepest opener %r at index %d" % (s[index], index))
                break
    return "\n".join(lines)


