PAIRS = {')': '(', ']': '[', '}': '{'}
OPENERS = set(PAIRS.values())


def validate(s):
    """Return a list of (index, character) for characters that are not brackets."""
    if not isinstance(s, str):
        raise TypeError("input must be a string")
    invalid = []
    for index in range(len(s)):
        if s[index] not in OPENERS and s[index] not in PAIRS:
            invalid.append((index, s[index]))
    return invalid


def is_brackets_balanced(s):
    """Return True if every bracket in s is closed in the correct order."""
    stack = []
    for index in range(len(s)):
        if s[index] in OPENERS:
            stack.append((index, s[index]))
        elif s[index] in PAIRS:
            if not stack or stack[-1][1] != PAIRS[s[index]]:
                return False
            stack.pop()
    return not stack


def first_mismatch(s):
    """Return the index of the first bracket that breaks the nesting, or None."""
    stack = []
    for index in range(len(s)):
        if s[index] in OPENERS:
            stack.append((index, s[index]))
        elif s[index] in PAIRS:
            if not stack or stack[-1][1] != PAIRS[s[index]]:
                return index
            stack.pop()
    if stack:
        return stack[0][0]
    return None


def depth_profile(s):
    """Return the nesting depth after each character of s."""
    depths = []
    depth = 0
    for char in s:
        if char in OPENERS:
            depth += 1
        elif char in PAIRS:
            depth -= 1
        depths.append(depth)
    return depths


def describe(s):
    """Build a human readable report about the bracket string s."""
    lines = []
    invalid = validate(s)
    for position in range(len(invalid)):
        lines.append("  invalid #%d: %r at index %d" % (position + 1, invalid[position][1], invalid[position][0]))
    balanced = is_brackets_balanced(s)
    lines.append("  balanced: %s" % balanced)
    if not balanced:
        lines.append("  first problem at index %d" % first_mismatch(s))
    else:
        profile = depth_profile(s)
        deepest = max(profile) if profile else 0
        lines.append("  maximum nesting depth: %d" % deepest)
        for index in range(len(profile)):
            if profile[index] == deepest and s[index] in OPENERS:
                lines.append("  deepest opener %r at index %d" % (s[index], index))
                break
    return "\n".join(lines)


def main():
    samples = ['()[]{}', '([{}])', '({[})', '', '(((', '){', '(a)b']
    for number in range(len(samples)):
        print("%d. %r" % (number + 1, samples[number]))
        print(describe(samples[number]))


if __name__ == '__main__':
    main()

