        try:
            numbers.append(int(token))
        except ValueError:
            raise ValueError("token %d (%r) is not an integer" % (position, token))
    return numbers


def validate(numbers):
    limit = len(numbers) - 1
    if limit < 1:
        raise ValueError("numbers must contain at least two elements")
    for index, value in enumerate(numbers):
        if value < 1 or value > limit:
            raise ValueError(
                "element at position %d is %d, outside 1..%d" % (index, value, limit)
            )
    return limit


def first_repeat(numbers):
    seen = {}
    for index, value in enumerate(numbers):
        if value in seen:
            return value, seen[value], index
        seen[value] = index
    raise ValueError("no number appears twice")


