def validate_meeting(meeting, label="meeting"):
    if not isinstance(meeting, (tuple, list)) or len(meeting) != 2:
        raise ValueError("%s must be a pair of times" % label)
    for index, value in enumerate(meeting):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("%s field %d must be an int" % (label, index))
    start, end = meeting
    if start > end:
        raise ValueError("%s starts after it ends" % label)
    return (start, end)


def has_overlap(meeting1, meeting2):
    start1, end1 = validate_meeting(meeting1, "meeting1")
    start2, end2 = validate_meeting(meeting2, "meeting2")
    return start1 < end2 and start2 < end1


def find_conflicts(schedule):
    conflicts = []
    for i, first in enumerate(schedule):
        for j, second in enumerate(schedule[i + 1:], start=i + 1):
            if has_overlap(first, second):
                conflicts.append((i, j))
    return conflicts


def format_time(minutes):
    return "%02d:%02d" % (minutes // 60, minutes % 60)


def describe_schedule(schedule):
    lines = []
    for index, meeting in enumerate(schedule):
        start, end = validate_meeting(meeting, "schedule[%d]" % index)
        lines.append("#%d %s-%s" % (index, format_time(start), format_time(end)))
    return lines


def busiest_slot(schedule):
    events = []
    for meeting in schedule:
        start, end = validate_meeting(meeting)
        events.append((start, 1))
        events.append((end, -1))
    events.sort()
    running = 0
    best_count = 0
    best_time = None
    for time, delta in events:
        running += delta
        if running > best_count:
            best_count = running
            best_time = time
    return best_time, best_count


def main():
    schedule = [(540, 600), (570, 630), (660, 720), (700, 705), (800, 800)]
    for line in describe_schedule(schedule):
