import re


def tokenize(text):
    return re.findall(r"[A-Za-z0-9']+", text)


def count_keyword_occurrences(text, keyword):
    if not isinstance(text, str) or not isinstance(keyword, str):
        raise TypeError("text and keyword must be strings")
    target = keyword.strip().lower()
    if not target:
        return 0
    return sum(1 for word in tokenize(text) if word.lower() == target)


def keyword_positions(text, keyword):
    target = keyword.strip().lower()
    positions = []
    for index, word in enumerate(tokenize(text)):
        if word.lower() == target:
            positions.append(index)
    return positions


def context_snippets(text, keyword, window=3):
    target = keyword.strip().lower()
    words = tokenize(text)
    snippets = []
    for index, word in enumerate(words):
        if word.lower() == target:
            start = max(0, index - window)
            snippets.append(" ".join(words[start:index + window + 1]))
    return snippets


def line_report(text, keyword):
    target = keyword.strip().lower()
    report = []
    for lineno, line in enumerate(text.splitlines(), start=1):
        hits = sum(1 for word in tokenize(line) if word.lower() == target)
        if hits:
            report.append((lineno, hits, line.strip()))
    return report


def summarize(text, keywords):
    return {keyword: count_keyword_occurrences(text, keyword) for keyword in keywords}


def format_summary(summary):
    lines = []
    width = max((len(k) for k in summary), default=0)
    ranked = sorted(summary.items(), key=lambda kv: (-kv[1], kv[0]))
    for rank, (keyword, count) in enumerate(ranked, start=1):
        lines.append("%2d. %-*s %d" % (rank, width, keyword, count))
    return "\n".join(lines)


def main():
    document = (
        "Hello world, hello Python!\n"
        "Python is fun, and Python is fast.\n"
        "The snake is not a Python, but the language is.\n"
    )
    keywords = ["python", "hello", "java", "is"]
    print("Keyword totals:")
    print(format_summary(summarize(document, keywords)))

    print("\nPer-line hits for 'python':")
    for entry_no, (lineno, hits, content) in enumerate(line_report(document, "python"), start=1):
        print("  %d) line %d (%d hit(s)): %s" % (entry_no, lineno, hits, content))

    print("\nContexts for 'python':")
    for snippet in context_snippets(document, "python"):
        print("  ..." + snippet + "...")

    print("\nWord indexes of 'is': %s" % keyword_positions(document, "is"))


if __name__ == "__main__":
    main()

