def validate_numbers(numbers):
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    if not numbers:
        raise ValueError("numbers must not be empty")
    for position, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(
                "element at index {} is not a number: {!r}".format(position, value)
            )
    return list(numbers)


def count_frequencies(values):
    counts = {}
    first_seen = {}
    for position, value in enumerate(values):
        if value in counts:
            counts[value] += 1
        else:
            counts[value] = 1
            first_seen[value] = position
    return counts, first_seen


def mode_positions(values, mode_value):
    return [position for position, value in enumerate(values) if value == mode_value]


def calculate_mode(numbers):
    values = validate_numbers(numbers)
    counts, first_seen = count_frequencies(values)
    mode_value = values[0]
    best_count = counts[mode_value]
    for value, count in counts.items():
        if count > best_count or (
            count == best_count and first_seen[value] < first_seen[mode_value]
        ):
            mode_value = value
            best_count = count
    return mode_value


def rank_values(values):
    counts, first_seen = count_frequencies(values)
    ordered = sorted(counts.items(), key=lambda item: (-item[1], first_seen[item[0]]))
    return [
        (rank, value, count)
        for rank, (value, count) in enumerate(ordered, start=1)
    ]


def running_modes(values):
    counts = {}
    best_value = None
    best_count = 0
    timeline = []
    for seen, value in enumerate(values, start=1):
        counts[value] = counts.get(value, 0) + 1
        if counts[value] > best_count:
            best_value = value
            best_count = counts[value]
        timeline.append((seen, best_value))
    return timeline


