def validate_numbers(numbers):
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    if not numbers:
        raise ValueError("numbers must not be empty")
    for position in range(len(numbers)):
        if isinstance(numbers[position], bool) or not isinstance(numbers[position], (int, float)):
            raise TypeError(
                "element at index {} is not a number: {!r}".format(position, numbers[position])
            )
    return list(numbers)


def count_frequencies(values):
    counts = {}
    first_seen = {}
    for position in range(len(values)):
        if values[position] in counts:
            counts[values[position]] += 1
        else:
            counts[values[position]] = 1
            first_seen[values[position]] = position
    return counts, first_seen


def mode_positions(values, mode_value):
    return [position for position in range(len(values)) if values[position] == mode_value]


def calculate_mode(numbers):
    values = validate_numbers(numbers)
    counts, first_seen = count_frequencies(values)
    mode_value = values[0]
    best_count = counts[mode_value]
    for value, count in counts.items():
        if count > best_count or (
            count == best_count and first_seen[value] < first_seen[mode_value]
        ):
            mode_value = value
            best_count = count
    return mode_value


def rank_values(values):
    counts, first_seen = count_frequencies(values)
    ordered = sorted(counts.items(), key=lambda item: (-item[1], first_seen[item[0]]))
    return [
        (rank + 1, ordered[rank][0], ordered[rank][1])
        for rank in range(len(ordered))
    ]


def running_modes(values):
    counts = {}
    best_value = None
    best_count = 0
    timeline = []
    for seen in range(len(values)):
        counts[values[seen]] = counts.get(values[seen], 0) + 1
        if counts[values[seen]] > best_count:
            best_value = values[seen]
            best_count = counts[values[seen]]
        timeline.append((seen + 1, best_value))
    return timeline


def format_report(numbers):
    values = validate_numbers(numbers)
    mode_value = calculate_mode(values)
    lines = ["mode = {} at positions {}".format(mode_value, mode_positions(values, mode_value))]
    for rank, value, count in rank_values(values):
        lines.append("  {}. {} appears {} time(s)".format(rank, value, count))
    for seen, running in running_modes(values):
        lines.append("  after {} value(s) the mode is {}".format(seen, running))
    return "\n".join(lines)


def main():
    datasets = [[1, 2, 2, 3, 3, 3, 4], [5, 5, 1, 1], [2.5, 2.5, 7, 7, 7], [42]]
    for case_number in range(len(datasets)):
