def count_char(text, char_to_count):
    """Return how many times char_to_count appears in text."""
    if not isinstance(text, str) or not isinstance(char_to_count, str):
        raise TypeError("text and char_to_count must be strings")
    if len(char_to_count) != 1:
        raise ValueError("char_to_count must be exactly one character")
    total = 0
    for character in text:
        if character == char_to_count:
            total += 1
    return total


def find_positions(text, char_to_count):
    """Return the zero-based indices where char_to_count occurs in text."""
    positions = []
    for index, character in enumerate(text):
        if character == char_to_count:
            positions.append(index)
    return positions


def format_positions(text, char_to_count):
    """Build a caret ruler marking every occurrence of char_to_count under text."""
    hits = set(find_positions(text, char_to_count))
    marks = []
    for index, character in enumerate(text):
        if index in hits:
            marks.append("^")
        else:
            marks.append("\t" if character == "\t" else " ")
    return "".join(marks)


def count_per_line(text, char_to_count):
    """Return (line number, count) pairs for each line of text."""
    tally = []
    for number, line in enumerate(text.splitlines(), start=1):
        tally.append((number, count_char(line, char_to_count)))
    return tally


def count_all_chars(text):
    """Return a dict mapping each character of text to its occurrence count."""
    counts = {}
    for character in text:
        counts[character] = counts.get(character, 0) + 1
    return counts


def most_frequent(text):
    """Return (character, count) for the most frequent character, ties by first appearance."""
    best_char = None
    best_count = 0
    for character, count in count_all_chars(text).items():
        if count > best_count:
            best_char = character
            best_count = count
    return best_char, best_count


def build_report(pairs):
    """Turn (text, char) pairs into numbered report lines."""
    lines = []
    for number, (text, char) in enumerate(pairs, start=1):
        count = count_char(text, char)
        lines.append("%d. %r contains %r %d time(s)" % (number, text, char, count))
        if "\n" in text:
            for lineno, line_count in count_per_line(text, char):
                lines.append("   line %d: %d" % (lineno, line_count))
        else:
            lines.append("   " + text)
            lines.append("   " + format_positions(text, char))
        top_char, top_count = most_frequent(text)
        lines.append("   most frequent: %r (%d)" % (top_char, top_count))
    return lines


def main():
    samples = [("banana", "a"), ("Mississippi", "s"), ("one\ntwo\nthree", "e")]
    for line in build_report(samples):
        print(line)
    for order, index in enumerate(find_positions("Mississippi", "i"), start=1):
        print("occurrence %d of 'i' is at index %d" % (order, index))


if __name__ == "__main__":
    main()

