def get_item_quantity(inventory, item_name):
    return inventory.get(item_name, 0)


def parse_inventory(lines):
    inventory = {}
    errors = []
    for line_no, raw in enumerate(lines, start=1):
        text = raw.strip()
        if not text or text.startswith('#'):
            continue
        parts = text.split(',')
        if len(parts) != 2:
            errors.append("line %d: expected 'name,quantity'" % line_no)
            continue
        name = parts[0].strip()
        try:
            quantity = int(parts[1].strip())
        except ValueError:
            errors.append("line %d: quantity %r is not an integer" % (line_no, parts[1].strip()))
            continue
        if not name:
            errors.append("line %d: missing item name" % line_no)
        elif quantity < 0:
            errors.append("line %d: negative quantity for %r" % (line_no, name))
        else:
            inventory[name] = inventory.get(name, 0) + quantity
    return inventory, errors


def lookup_report(inventory, requested):
    rows = []
    for position, item_name in enumerate(requested, start=1):
        quantity = get_item_quantity(inventory, item_name)
        status = 'in stock' if quantity else 'unavailable'
        rows.append("%2d. %-10s %4d  (%s)" % (position, item_name, quantity, status))
    return rows


def low_stock_items(inventory, threshold):
    return sorted(name for name in inventory if get_item_quantity(inventory, name) < threshold)


def restock_plan(inventory, threshold):
    plan = []
    for rank, name in enumerate(low_stock_items(inventory, threshold), start=1):
        plan.append((rank, name, threshold - get_item_quantity(inventory, name)))
    return plan


def main():
    raw_lines = [
        '# name,quantity',
        'apple, 10',
        'banana, 5',
        'cherry, 2',
        'apple, 4',
        'date, many',
        'eggplant',
    ]
    inventory, errors = parse_inventory(raw_lines)
    for number, message in enumerate(errors, start=1):
        print("warning %d: %s" % (number, message))

    print('\nLookups:')
    for line in lookup_report(inventory, ['apple', 'banana', 'orange']):
        print(line)

    threshold = 6
    print('\nRestock plan (threshold %d):' % threshold)
    for rank, name, needed in restock_plan(inventory, threshold):
        print("%d) order %d more %s" % (rank, needed, name))

    print('\nFull inventory:')
    for slot, (name, quantity) in enumerate(sorted(inventory.items()), start=1):
        print("[%d] %s = %d" % (slot, name, quantity))


if __name__ == '__main__':
    main()

