def validate_matrix(matrix):
    """Check that matrix is a rectangular list of lists of numbers."""
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of lists")
    width = None
    for i in range(len(matrix)):
        if not isinstance(matrix[i], list):
            raise TypeError("row %d is not a list" % i)
        if width is None:
            width = len(matrix[i])
        elif len(matrix[i]) != width:
            raise ValueError(
                "row %d has length %d, expected %d" % (i, len(matrix[i]), width))
        for j in range(len(matrix[i])):
            if isinstance(matrix[i][j], bool) or not isinstance(matrix[i][j], (int, float)):
                raise TypeError("entry (%d, %d) is not a number" % (i, j))
    return len(matrix), width or 0


def transpose_matrix(matrix):
    """Return the transpose of a rectangular matrix as a new list of lists."""
    rows, cols = validate_matrix(matrix)
    result = [[None] * rows for _ in range(cols)]
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            result[j][i] = matrix[i][j]
    return result


def column_widths(matrix):
    """Width in characters needed by each column when rendered."""
    widths = []
    for row in matrix:
        for j in range(len(row)):
            text = format(row[j])
            if j >= len(widths):
                widths.append(len(text))
            elif len(text) > widths[j]:
                widths[j] = len(text)
    return widths


def format_matrix(matrix):
    """Render a matrix as aligned text rows."""
    widths = column_widths(matrix)
    lines = []
    for row in matrix:
        cells = []
        for j in range(len(row)):
            cells.append(format(row[j]).rjust(widths[j]))
        lines.append("| " + "  ".join(cells) + " |")
    return "\n".join(lines) if lines else "(empty)"


def main():
    cases = [
        [[1, 2, 3], [4, 5, 6]],
        [[10]],
        [[1.5, -2], [300, 4], [0, 7]],
        [],
    ]
    for case in cases:
        rows, cols = validate_matrix(case)
        transposed = transpose_matrix(case)
        print("%dx%d -> %dx%d" % (rows, cols, cols, rows))
        print(format_matrix(case))
        print("becomes")
        print(format_matrix(transposed))
        print()


if __name__ == "__main__":
    main()

