def parse_digits(card_number):
    if not isinstance(card_number, str):
        raise TypeError("card_number must be a string")
    digits = []
    for position, char in enumerate(card_number):
        if not char.isdigit():
            raise ValueError("non-digit %r at position %d" % (char, position))
        digits.append(int(char))
    if not digits:
        raise ValueError("card_number must contain at least one digit")
    return digits


def doubled_digits(digits):
    weighted = []
    for index, digit in enumerate(digits):
        if (len(digits) - index) % 2 == 0:
            product = digit * 2
            weighted.append(product - 9 if product > 9 else product)
        else:
            weighted.append(digit)
    return weighted


def luhn_sum(card_number):
    return sum(doubled_digits(parse_digits(card_number)))


def is_valid_luhn(card_number):
    return luhn_sum(card_number) % 10 == 0


def format_card_number(card_number):
    digits = parse_digits(card_number)
    groups = []
    for index, digit in enumerate(digits):
        if index % 4 == 0:
            groups.append("")
        groups[-1] += str(digit)
    return " ".join(groups)


def describe_steps(card_number):
    digits = parse_digits(card_number)
    weighted = doubled_digits(digits)
    lines = []
    for index, digit in enumerate(digits):
        marker = "x2" if (len(digits) - index) % 2 == 0 else "  "
        lines.append("  pos %2d: %d %s -> %d" % (index, digit, marker, weighted[index]))
    lines.append("  checksum: %d" % sum(weighted))
    return lines


def report(card_numbers, verbose=False):
    for position, number in enumerate(card_numbers):
        try:
            verdict = "VALID" if is_valid_luhn(number) else "INVALID"
            print("%d. %s -> %s" % (position + 1, format_card_number(number), verdict))
            if verbose:
                for line in describe_steps(number):
                    print(line)
        except (TypeError, ValueError) as error:
            print("%d. %s -> ERROR (%s)" % (position + 1, number, error))


def main():
    samples = ["49927398716", "1234567890123456", "79927398713", "4992a398716"]
    report(samples)
    print()
    print("Detailed trace for the first sample:")
    for line in describe_steps(samples[0]):
        print(line)


if __name__ == "__main__":
    main()

