def _validate(number):
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("number must be an int, got %r" % (number,))
    return number


def digits_of(number):
    return [int(character) for character in str(abs(number))]


def is_palindromic_number(number):
    _validate(number)
    if number < 0:
        return False
    digits = digits_of(number)
    last = len(digits) - 1
    for index, digit in enumerate(digits):
        if index >= last - index:
            break
        if digit != digits[last - index]:
            return False
    return True


def palindromic_positions(numbers):
    positions = []
    for index, value in enumerate(numbers):
        if is_palindromic_number(value):
            positions.append(index)
    return positions


def palindromes_in_range(start, end):
    return [value for value in range(start, end + 1) if is_palindromic_number(value)]


def next_palindrome_after(number):
    _validate(number)
    candidate = number + 1
    while not is_palindromic_number(candidate):
        candidate += 1
    return candidate


def count_by_length(palindromes):
    counts = {}
    for value in palindromes:
        length = len(digits_of(value))
        counts[length] = counts.get(length, 0) + 1
    return counts


def format_report(palindromes):
    lines = []
    for rank, value in enumerate(palindromes, start=1):
        lines.append("%3d. %d" % (rank, value))
    counts = count_by_length(palindromes)
    for length in sorted(counts):
        lines.append("length %d -> %d palindrome(s)" % (length, counts[length]))
    return "\n".join(lines)


def main():
