import re
from collections import OrderedDict

EMAIL_PATTERN = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+")


def extract_emails(text):
    """Return every valid-looking email address found in text, in order."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    found = []
    for match in EMAIL_PATTERN.finditer(text):
        address = match.group(0).rstrip(".")
        if address.count("@") == 1 and "." in address.split("@", 1)[1]:
            found.append(address)
    return found


def emails_by_line(text):
    """Map 1-based line numbers to the emails appearing on that line."""
    located = []
    for index, line in enumerate(text.splitlines(), start=1):
        addresses = extract_emails(line)
        if addresses:
            located.append((index, addresses))
    return located


def first_positions(emails):
    """Return an ordered mapping of each address to the index it first appeared at."""
    positions = OrderedDict()
    for index, address in enumerate(emails):
        if address.lower() not in positions:
            positions[address.lower()] = index
    return positions


def group_by_domain(emails):
    groups = OrderedDict()
    for address in emails:
        domain = address.split("@", 1)[1].lower()
        groups.setdefault(domain, []).append(address)
    return groups


def format_report(text):
    emails = extract_emails(text)
    lines = ["found %d address(es)" % len(emails)]
    for number, address in enumerate(emails, start=1):
        lines.append("  %d. %s" % (number, address))
    for line_number, addresses in emails_by_line(text):
        lines.append("  line %d -> %s" % (line_number, ", ".join(addresses)))
    for rank, (domain, members) in enumerate(group_by_domain(emails).items(), start=1):
        lines.append("  domain #%d %s (%d)" % (rank, domain, len(members)))
    duplicates = len(emails) - len(first_positions(emails))
    if duplicates:
        lines.append("  %d duplicate(s) ignored when counting unique addresses" % duplicates)
    return "\n".join(lines)


def main():
    samples = [
        "Contact us at info@example.com or support@test.org.",
        "No emails here.",
        "Sales: sales@shop.co.uk\nBilling: billing@shop.co.uk, sales@shop.co.uk\nEnd.",
    ]
    for sample_number, sample in enumerate(samples, start=1):
        print("sample %d: %r" % (sample_number, sample))
        print(format_report(sample))
        print()


if __name__ == "__main__":
    main()

