def validate_2x2(matrix, name):
    if not isinstance(matrix, list) or len(matrix) != 2:
        raise ValueError(f"{name} must be a list of 2 rows")
    for i, row in enumerate(matrix):
        if not isinstance(row, list) or len(row) != 2:
            raise ValueError(f"{name} row {i} must be a list of 2 numbers")
        for j, value in enumerate(row):
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                raise ValueError(f"{name}[{i}][{j}] is not a number: {value!r}")


def multiply_2x2_matrices(matrix_a, matrix_b):
    validate_2x2(matrix_a, "matrix_a")
    validate_2x2(matrix_b, "matrix_b")
    result = [[0, 0], [0, 0]]
    for i, row in enumerate(matrix_a):
        for k, a_value in enumerate(row):
            for j, b_value in enumerate(matrix_b[k]):
                result[i][j] += a_value * b_value
    return result


def column_widths(matrix):
    widths = [0, 0]
    for row in matrix:
        for j, value in enumerate(row):
            widths[j] = max(widths[j], len(str(value)))
    return widths


def format_matrix(matrix):
    widths = column_widths(matrix)
    lines = []
    for row in matrix:
        cells = []
        for j, value in enumerate(row):
            cells.append(str(value).rjust(widths[j]))
        lines.append("[ " + "  ".join(cells) + " ]")
    return lines


def format_product(matrix_a, matrix_b, product):
    blocks = [format_matrix(matrix_a), format_matrix(matrix_b), format_matrix(product)]
    separators = [" x ", " = "]
    lines = []
    for line_index, first_line in enumerate(blocks[0]):
        parts = [first_line]
        for block_index, block in enumerate(blocks[1:]):
            parts.append(separators[block_index] if line_index == 0 else " " * 3)
            parts.append(block[line_index])
        lines.append("".join(parts))
    return "\n".join(lines)


def main():
    cases = [
        ([[1, 2], [3, 4]], [[5, 6], [7, 8]]),
        ([[1, 0], [0, 1]], [[10, 20], [30, 40]]),
        ([[2, -1], [0, 3]], [[1, 4], [5, -2]]),
    ]
    for matrix_a, matrix_b in cases:
        product = multiply_2x2_matrices(matrix_a, matrix_b)
        print(format_product(matrix_a, matrix_b, product))
        print(f"product as list: {product}")
        print()


if __name__ == "__main__":
