from collections import OrderedDict


def _comparable(left, right):
    try:
        left < right
    except TypeError:
        return False
    return True


def _validate_keys(input_dict):
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict, got %s" % type(input_dict).__name__)
    keys = list(input_dict)
    for index, key in enumerate(keys):
        if index and not _comparable(keys[index - 1], key):
            raise TypeError(
                "key at position %d (%r) cannot be compared with %r"
                % (index, key, keys[index - 1])
            )
    return keys


def sort_dict_by_key(input_dict):
    keys = _validate_keys(input_dict)
    return OrderedDict((key, input_dict[key]) for key in sorted(keys))


def key_positions(keys):
    positions = {}
    for index, key in enumerate(keys):
        positions[key] = index
    return positions


def format_sorted(items):
    lines = []
    for rank, (key, value) in enumerate(items, start=1):
        lines.append("%d. %r -> %r" % (rank, key, value))
    return lines


def first_out_of_order(keys):
    for index, key in enumerate(keys):
        if index and keys[index - 1] > key:
            return index
    return -1


def describe_shift(original_keys, sorted_keys):
    positions = key_positions(sorted_keys)
    moves = []
    for index, key in enumerate(original_keys):
        target = positions[key]
        moves.append((key, index, target, target - index))
    return moves


def main():
    samples = [
        {'b': 2, 'a': 1, 'c': 3},
        {'z': 26, 'y': 25},
        {'apple': 3, 'banana': 1, 'cherry': 2},
        {3: 'three', 1: 'one', 2: 'two'},
    ]
    for case, sample in enumerate(samples, start=1):
        result = sort_dict_by_key(sample)
        print("Case %d: %r" % (case, dict(result)))
        for line in format_sorted(list(result.items())):
            print("   " + line)
        break_at = first_out_of_order(list(sample))
