from collections import OrderedDict


def _comparable(left, right):
    try:
        left < right
    except TypeError:
        return False
    return True


def _validate_keys(input_dict):
    if not isinstance(input_dict, dict):
        raise TypeError("input_dict must be a dict, got %s" % type(input_dict).__name__)
    keys = list(input_dict)
    for index in range(len(keys)):
        if index and not _comparable(keys[index - 1], keys[index]):
            raise TypeError(
                "key at position %d (%r) cannot be compared with %r"
                % (index, keys[index], keys[index - 1])
            )
    return keys


def sort_dict_by_key(input_dict):
    keys = _validate_keys(input_dict)
    return OrderedDict((key, input_dict[key]) for key in sorted(keys))


def key_positions(keys):
    positions = {}
    for index in range(len(keys)):
        positions[keys[index]] = index
    return positions


def format_sorted(items):
    lines = []
    for rank in range(len(items)):
        lines.append("%d. %r -> %r" % (rank + 1, items[rank][0], items[rank][1]))
    return lines


def first_out_of_order(keys):
    for index in range(len(keys)):
        if index and keys[index - 1] > keys[index]:
            return index
    return -1


def describe_shift(original_keys, sorted_keys):
    positions = key_positions(sorted_keys)
    moves = []
    for index in range(len(original_keys)):
        target = positions[original_keys[index]]
        moves.append((original_keys[index], index, target, target - index))
    return moves


def main():
    samples = [
        {'b': 2, 'a': 1, 'c': 3},
        {'z': 26, 'y': 25},
        {'apple': 3, 'banana': 1, 'cherry': 2},
        {3: 'three', 1: 'one', 2: 'two'},
    ]
    for case in range(len(samples)):
        result = sort_dict_by_key(samples[case])
        print("Case %d: %r" % (case + 1, dict(result)))
        for line in format_sorted(list(result.items())):
            print("   " + line)
        break_at = first_out_of_order(list(samples[case]))
        if break_at == -1:
            print("   input was already sorted")
        else:
            print("   input first broke order at position %d" % break_at)
        for key, old, new, delta in describe_shift(list(samples[case]), list(result)):
            print("   %r moved %d -> %d (%+d)" % (key, old, new, delta))


if __name__ == "__main__":
    main()

