from datetime import date
import sys

MONTH_NAMES = ("January", "February", "March", "April", "May", "June", "July",
               "August", "September", "October", "November", "December")
WEEKDAY_NAMES = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday",
                 "Saturday", "Sunday")
FIELD_NAMES = ("year", "month", "day")


def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def month_lengths(year):
    return (31, 29 if is_leap(year) else 28, 31, 30, 31, 30,
            31, 31, 30, 31, 30, 31)


def parse_date(text):
    parts = text.split("-")
    if len(parts) != 3:
        raise ValueError("expected the form YYYY-MM-DD")
    values = []
    for index, part in enumerate(parts):
        cleaned = part.strip()
        if not cleaned.isdigit():
            raise ValueError("%s must be a number, got %r" % (FIELD_NAMES[index], part))
        values.append(int(cleaned))
    return tuple(values)


def column_widths(rows):
    widths = [0] * len(rows[0])
    for row in rows:
        for index, cell in enumerate(row):
            widths[index] = max(widths[index], len(cell))
    return widths


def days_since(year, month, day):
    if month < 1 or month > 12:
        raise ValueError("month out of range: %d" % month)
