def parse_csv_line(line):
    """Split a single CSV row into a list of field strings."""
    fields = []
    current = []
    in_quotes = False
    skip_next = False
    for index, char in enumerate(line):
        if skip_next:
            skip_next = False
            continue
        if char == '"':
            if in_quotes and index + 1 < len(line) and line[index + 1] == '"':
                current.append('"')
                skip_next = True
            else:
                in_quotes = not in_quotes
        elif char == ',' and not in_quotes:
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    fields.append(''.join(current))
    return fields


def parse_csv_text(text):
    """Parse a multi-line CSV document into a list of rows."""
    rows = []
    for line in text.splitlines():
        if line.strip():
            rows.append(parse_csv_line(line))
    return rows


def find_width_problems(header, rows):
    """Report data rows whose field count differs from the header's."""
    problems = []
    for row_index, row in enumerate(rows):
        if len(row) != len(header):
            problems.append((row_index, len(row)))
    return problems


def column_widths(header, rows):
    """Compute the display width needed for each header column."""
    widths = [len(name) for name in header]
    for row in rows:
        for column, field in enumerate(row):
            if column < len(widths):
                widths[column] = max(widths[column], len(field))
    return widths


def format_row(row, widths):
    cells = []
    for column, field in enumerate(row):
        padding = widths[column] if column < len(widths) else len(field)
        cells.append(field.ljust(padding))
    return ' | '.join(cells).rstrip()


def format_table(header, rows):
    widths = column_widths(header, rows)
    lines = [format_row(header, widths), '-+-'.join('-' * w for w in widths)]
    for row in rows:
        lines.append(format_row(row, widths))
    return '\n'.join(lines)


def main():
    document = (
        'name,color,notes\n'
        'apple,red,"sweet, crisp"\n'
        'banana,yellow,\n'
        'cherry,,"said ""tart"""\n'
        'plum,purple,soft,extra\n'
    )
    header, *rows = parse_csv_text(document)
    print(format_table(header, rows))
    for row_index, count in find_width_problems(header, rows):
        print('data row {}: expected {} fields, got {}'.format(
            row_index, len(header), count))
    for position, name in enumerate(header):
        values = [row[position] for row in rows if position < len(row)]
        empty = sum(1 for value in values if value == '')
        print('column {} ({}): {} values, {} empty'.format(
            position, name, len(values), empty))


if __name__ == '__main__':
    main()

