class ToDoList:
    """A minimal to-do list that tracks task names and their completion state."""

    def __init__(self):
        self.tasks = []

    def _index_of(self, task_name):
        for index, task in enumerate(self.tasks):
            if task["name"] == task_name:
                return index
        return -1

    def add_task(self, task_name):
        if not isinstance(task_name, str) or not task_name.strip():
            raise ValueError("task name must be a non-empty string")
        name = task_name.strip()
        if self._index_of(name) != -1:
            return False
        self.tasks.append({"name": name, "completed": False})
        return True

    def mark_completed(self, task_name):
        index = self._index_of(task_name.strip() if isinstance(task_name, str) else task_name)
        if index == -1:
            return False
        self.tasks[index]["completed"] = True
        return True

    def get_pending_tasks(self):
        return [task["name"] for task in self.tasks if not task["completed"]]

    def pending_summaries(self):
        summaries = []
        for index, task in enumerate(self.tasks):
            if not task["completed"]:
                summaries.append("item %d: %s" % (index + 1, task["name"]))
        return summaries

    def numbered_listing(self):
        lines = []
        for index, task in enumerate(self.tasks):
            mark = "x" if task["completed"] else " "
            lines.append("{:>2}. [{}] {}".format(index + 1, mark, task["name"]))
        return lines


def run_script(todo, commands):
    """Apply "add <name>" / "done <name>" commands, returning error messages."""
    errors = []
    for index, command in enumerate(commands):
        verb, _, argument = command.partition(" ")
        if verb == "add":
            if not todo.add_task(argument):
                errors.append("line %d: duplicate task %r" % (index + 1, argument.strip()))
        elif verb == "done":
            if not todo.mark_completed(argument):
                errors.append("line %d: unknown task %r" % (index + 1, argument.strip()))
        else:
            errors.append("line %d: unknown command %r" % (index + 1, verb))
    return errors


def format_report(todo):
    lines = todo.numbered_listing()
    summaries = todo.pending_summaries()
    lines.append("pending: %d of %d" % (len(summaries), len(todo.tasks)))
    for rank, summary in enumerate(summaries):
        lines.append("  next #%d -> %s" % (rank + 1, summary))
    return lines


def main():
    todo = ToDoList()
    script = [
        "add Buy milk",
        "add Walk dog",
        "add Buy milk",
        "done Buy milk",
        "done Pay rent",
        "add Write report",
    ]
    for message in run_script(todo, script):
        print("warning:", message)
    for line in format_report(todo):
        print(line)
    print("get_pending_tasks() ->", todo.get_pending_tasks())


if __name__ == "__main__":
    main()

