DIGITS = "0123456789ABCDEF"


def convert_base(number, base):
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError("number must be an integer")
    if not isinstance(base, int) or isinstance(base, bool):
        raise TypeError("base must be an integer")
    if not 2 <= base <= 16:
        raise ValueError("base must be between 2 and 16")
    if number == 0:
        return "0"
    negative = number < 0
    value = abs(number)
    digits = []
    while value:
        value, remainder = divmod(value, base)
        digits.append(DIGITS[remainder])
    if negative:
        digits.append("-")
    return "".join(reversed(digits))


def parse_base(text, base):
    text = text.strip().upper()
    negative = text.startswith("-")
    if negative:
        text = text[1:]
    if not text:
        raise ValueError("empty numeral")
    total = 0
    for position in range(len(text)):
        digit = DIGITS.find(text[position])
        if digit < 0 or digit >= base:
            raise ValueError("invalid digit %r at position %d" % (text[position], position))
        total = total * base + digit
    return -total if negative else total


def digit_place_values(text, base):
    digits = text.lstrip("-")
    values = []
    for position in range(len(digits)):
        values.append(DIGITS.index(digits[position]) * base ** (len(digits) - 1 - position))
    return values


def column_widths(numbers, bases):
    widths = []
    for base in bases:
        labels = ["base%d" % base] + [convert_base(number, base) for number in numbers]
        widths.append(max(len(label) for label in labels) + 2)
    return widths


def format_table(numbers, bases):
    widths = column_widths(numbers, bases)
    header = "decimal".rjust(8)
    for column in range(len(bases)):
        header += ("base%d" % bases[column]).rjust(widths[column])
    lines = [header]
    for number in numbers:
        row = str(number).rjust(8)
        for column in range(len(bases)):
            row += convert_base(number, bases[column]).rjust(widths[column])
        lines.append(row)
    return "\n".join(lines)


def main():
    samples = [10, 255, 4095, -73, 0]
    print(format_table(samples, [2, 8, 16]))
    for index in range(len(samples)):
        text = convert_base(samples[index], 16)
        print("sample %d: %d -> %s -> %d" % (index, samples[index], text, parse_base(text, 16)))
    octal = convert_base(4095, 8)
    values = digit_place_values(octal, 8)
    for position in range(len(octal)):
        print("position %d: digit %s contributes %d" % (position, octal[position], values[position]))


if __name__ == "__main__":
    main()

