def cartesian_product(list1, list2):
    """Return every ordered pair (a, b) with a from list1 and b from list2."""
    return [(a, b) for a in list1 for b in list2]


def numbered_lines(pairs):
    """Return one numbered text line per pair."""
    lines = []
    for index, pair in enumerate(pairs):
        lines.append("{:>3}. ({!r}, {!r})".format(index + 1, pair[0], pair[1]))
    return lines


def build_grid(list1, list2, pairs):
    """Lay the pairs out as a table: list1 down the rows, list2 across."""
    span = len(list2)
    rows = [[""] + [repr(b) for b in list2]]
    for index, a in enumerate(list1):
        chunk = pairs[index * span:(index + 1) * span]
        rows.append([repr(a)] + ["({!r}, {!r})".format(p[0], p[1]) for p in chunk])
    return rows


def column_widths(rows):
    """Return the width needed by each column of the table."""
    widths = []
    for row in rows:
        for column, cell in enumerate(row):
            if column < len(widths):
                widths[column] = max(widths[column], len(cell))
            else:
                widths.append(len(cell))
    return widths


def render_table(rows):
    """Turn the grid into aligned text lines with a header rule."""
    widths = column_widths(rows)
    lines = []
    for index, row in enumerate(rows):
        cells = [cell.ljust(width) for cell, width in zip(row, widths)]
        lines.append(" | ".join(cells).rstrip())
        if index == 0:
            lines.append("-+-".join("-" * width for width in widths))
    return lines


def main():
    datasets = [
        ([1, 2], ["a", "b"]),
        ([1], []),
        (["x", "y", "z"], [True, False]),
    ]
    for position, dataset in enumerate(datasets):
        left, right = dataset
        pairs = cartesian_product(left, right)
        print("Case {}: cartesian_product({!r}, {!r})".format(position + 1, left, right))
        print("  result: {!r}".format(pairs))
        for line in numbered_lines(pairs):
            print("  " + line)
        if pairs:
            for line in render_table(build_grid(left, right, pairs)):
                print("  " + line)
        print()


if __name__ == "__main__":
    main()

