def validate_inputs(values):
    """Return the values as a list, rejecting anything that is not a non-negative int."""
    checked = []
    for index, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("input #{0} is not an integer: {1!r}".format(index, value))
        if value < 0:
            raise ValueError("input #{0} is negative: {1}".format(index, value))
        checked.append(value)
    return checked


def bit_string(n):
    """Binary digits of n, most significant first."""
    return bin(n)[2:]


def set_bit_positions(n):
    """Indices (0 = least significant) of the '1' bits of n."""
    digits = list(reversed(bit_string(n)))
    positions = []
    for index, digit in enumerate(digits):
        if digit == "1":
            positions.append(index)
    return positions


def count_set_bits(n):
    """Number of '1' bits in the binary representation of the non-negative integer n."""
    validate_inputs((n,))
    return len(set_bit_positions(n))


def group_nibbles(n):
    """Binary digits of n, zero padded and split into groups of four."""
    digits = bit_string(n)
    padded = "0" * ((-len(digits)) % 4) + digits
    groups = []
    for index, digit in enumerate(padded):
        if index % 4 == 0:
            groups.append("")
        groups[-1] += digit
    return groups


def popcount_histogram(values):
    """List whose i-th entry counts how many values have exactly i set bits."""
    weights = [count_set_bits(value) for value in validate_inputs(values)]
    counts = [0] * (max(weights, default=0) + 1)
    for weight in weights:
        counts[weight] += 1
    return counts


def format_report_lines(values):
    checked = validate_inputs(values)
    lines = ["  # |      value | binary (nibbles)     | set bits | positions"]
    for index, value in enumerate(checked):
        binary = " ".join(group_nibbles(value))
        positions = ", ".join(str(p) for p in set_bit_positions(value))
        lines.append("{0:>3} | {1:>10} | {2:<20} | {3:>8} | {4}".format(
            index + 1, value, binary, count_set_bits(value), positions or "-"))
    return lines


def format_histogram_lines(values):
    histogram = popcount_histogram(values)
    lines = ["set bits | numbers"]
    for weight, count in enumerate(histogram):
        lines.append("{0:>8} | {1}".format(weight, "*" * count))
    return lines


def main():
    numbers = [0, 1, 7, 10, 31, 255, 1023, 4096, 123456789]
    for line in format_report_lines(numbers):
        print(line)
    print()
    for line in format_histogram_lines(numbers):
        print(line)
    print()
    print("total set bits:", sum(count_set_bits(value) for value in numbers))


if __name__ == "__main__":
    main()

