def generate_permutations(lst):
    """Return a list of all orderings of the elements in lst."""
    if len(lst) <= 1:
        return [list(lst)]
    permutations = []
    for index in range(len(lst)):
        rest = lst[:index] + lst[index + 1:]
        for sub in generate_permutations(rest):
            permutations.append([lst[index]] + sub)
    return permutations


def count_inversions(perm):
    """Number of pairs that appear out of ascending order in perm."""
    inversions = 0
    for i in range(len(perm)):
        for right in perm[i + 1:]:
            if perm[i] > right:
                inversions += 1
    return inversions


def fixed_points(perm, original):
    """Positions where perm still holds the element from original."""
    positions = []
    for position in range(len(perm)):
        if perm[position] == original[position]:
            positions.append(position)
    return positions


def derangements(perms, original):
    """Permutations that move every element away from its original slot."""
    return [p for p in perms if not fixed_points(p, original)]


def rank_of(perm, perms):
    """Index of perm within perms, or -1 when it is absent."""
    for rank in range(len(perms)):
        if perms[rank] == perm:
            return rank
    return -1


def format_permutations(perms, original):
    """Render each permutation with its index, inversions and fixed points."""
    lines = []
    width = len(str(len(perms)))
    for index in range(len(perms)):
        shown = ", ".join(str(item) for item in perms[index])
        marks = fixed_points(perms[index], original)
        lines.append(
            "{0:>{1}}: [{2}] inversions={3} fixed={4}".format(
                index, width, shown, count_inversions(perms[index]), marks or "-"
            )
        )
    return "\n".join(lines)


def main():
    samples = [[1, 2], ['a'], ['x', 'y', 'z']]
    for case in range(len(samples)):
        perms = generate_permutations(samples[case])
        print("Case {0}: {1} -> {2} permutations".format(case, samples[case], len(perms)))
        print(format_permutations(perms, samples[case]))
        moved = derangements(perms, samples[case])
        print("derangements: {0}".format(moved if moved else "none"))
        for slot in range(len(moved)):
            print("  derangement {0} has rank {1}".format(slot, rank_of(moved[slot], perms)))
        print()


if __name__ == "__main__":
    main()

