def is_prime(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("is_prime expects an int")
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 2
    return True


def sieve_primes(limit):
    flags = [True] * (limit + 1)
    for value, still_prime in enumerate(flags):
        if value < 2:
            flags[value] = False
        elif still_prime:
            for multiple in range(value * value, limit + 1, value):
                flags[multiple] = False
    return [value for value, prime in enumerate(flags) if prime]


def prime_factors(n):
    if n < 2:
        return []
    factors = []
    remaining = n
    candidate = 2
    while candidate * candidate <= remaining:
        exponent = 0
        while remaining % candidate == 0:
            remaining //= candidate
            exponent += 1
        if exponent:
            factors.append((candidate, exponent))
        candidate += 1 if candidate == 2 else 2
    if remaining > 1:
        factors.append((remaining, 1))
    return factors


def format_factorization(n):
    factors = prime_factors(n)
    if not factors:
        return "no prime factorization"
    parts = []
    for index, pair in enumerate(factors):
        base, exponent = pair
        piece = str(base) if exponent == 1 else "{}^{}".format(base, exponent)
        parts.append(piece if index == 0 else " * " + piece)
    return "".join(parts)


