def _validate_sides(sides):
    for position, side in enumerate(sides, start=1):
        if not isinstance(side, (int, float)) or isinstance(side, bool):
            raise TypeError("side%d must be an int or a float" % position)
        if side <= 0:
            raise ValueError("side%d must be positive, got %r" % (position, side))
    for index, side in enumerate(sides):
        others = [value for other_index, value in enumerate(sides) if other_index != index]
        if sum(others) <= side:
            raise ValueError(
                "sides %r violate the triangle inequality at side%d" % (sides, index + 1)
            )


def calculate_triangle_perimeter(side1, side2, side3):
    sides = (side1, side2, side3)
    _validate_sides(sides)
    return side1 + side2 + side3


def classify_triangle(side1, side2, side3):
    sides = sorted((side1, side2, side3))
    _validate_sides(sides)
    matches = 0
    for index, side in enumerate(sides[1:]):
        if side == sides[index]:
            matches += 1
    if matches == 2:
        return "equilateral"
    if matches == 1:
        return "isosceles"
    return "scalene"


def format_side_list(sides):
    parts = []
    for index, side in enumerate(sides):
        label = "a" if index == 0 else ("b" if index == 1 else "c")
        parts.append("%s=%g" % (label, side))
    return ", ".join(parts)


def build_report(triangles):
    lines = ["#  sides                    perimeter  kind"]
    for number, triangle in enumerate(triangles, start=1):
        perimeter = calculate_triangle_perimeter(*triangle)
        kind = classify_triangle(*triangle)
        lines.append(
            "%-2d %-24s %-10g %s" % (number, format_side_list(triangle), perimeter, kind)
        )
    return "\n".join(lines)


def longest_perimeter_index(triangles):
    best_index = None
    best_value = None
    for index, triangle in enumerate(triangles):
        perimeter = calculate_triangle_perimeter(*triangle)
        if best_value is None or perimeter > best_value:
            best_index, best_value = index, perimeter
    return best_index


def main():
    triangles = [
        (3, 4, 5),
        (7.5, 6, 8.5),
        (2, 2, 2),
        (5, 5, 8),
    ]
    print(build_report(triangles))
    winner = longest_perimeter_index(triangles)
    print(
        "largest perimeter: triangle #%d (%g)"
        % (winner + 1, calculate_triangle_perimeter(*triangles[winner]))
    )


if __name__ == "__main__":
    main()

