def _key(value):
    """Return a hashable identity for *value* so unhashable items work too."""
    try:
        hash(value)
    except TypeError:
        return ("repr", repr(value))
    return ("value", value)


def first_positions(items):
    """Map the identity of every distinct element to its first index."""
    positions = {}
    for index, value in enumerate(items):
        positions.setdefault(_key(value), index)
    return positions


def group_positions(items):
    """Map the identity of every distinct element to all indices holding it."""
    groups = {}
    for index, value in enumerate(items):
        groups.setdefault(_key(value), []).append(index)
    return groups


def remove_duplicates_unordered(items):
    """Return a new list holding each distinct element of *items* exactly once."""
    positions = first_positions(items)
    return [items[index] for index in positions.values()]


def duplicate_indices(items):
    """Indices whose element already appeared earlier in the list."""
    positions = first_positions(items)
    return [
        index
        for index, value in enumerate(items)
        if positions[_key(value)] != index
    ]


def format_unique_table(unique):
    """Render the de-duplicated elements as numbered report lines."""
    lines = []
    for index, value in enumerate(unique):
        lines.append("  %d. %r" % (index, value))
    return lines


def format_report(items):
    """Build a human readable summary of the de-duplication of *items*."""
    unique = remove_duplicates_unordered(items)
    groups = group_positions(items)
    lines = ["input  : %r" % (items,), "unique : %d element(s)" % len(unique)]
    lines.extend(format_unique_table(unique))
    for index, value in enumerate(items):
        where = groups[_key(value)]
        if where[0] == index:
            spots = ", ".join(str(i) for i in where)
            lines.append("  [%d] %r kept, seen at %s" % (index, value, spots))
        else:
            lines.append("  [%d] %r duplicate of index %d" % (index, value, where[0]))
    dropped = duplicate_indices(items)
    lines.append("dropped indices: %s" % (", ".join(str(i) for i in dropped) or "none"))
    return "\n".join(lines)


def main():
    samples = [
        [1, 2, 2, 3, 1, 4],
        ['a', 'b', 'a', 'c'],
        [],
        [7, 'x', 'x', 3.5, 7, 7],
        [[1], [1], [2]],
    ]
    for index, sample in enumerate(samples):
        print("sample %d" % index)
        print(format_report(sample))
        print()


if __name__ == "__main__":
    main()

