def parse_numbers(tokens):
    """Convert a sequence of textual tokens into floats."""
    values = []
    for position in range(len(tokens)):
        try:
            values.append(float(tokens[position]))
        except (TypeError, ValueError):
            raise ValueError("token %d is not numeric: %r" % (position, tokens[position]))
    return values


def calculate_average(numbers):
    """Return the mean of numbers as a float, or 0.0 for an empty list."""
    total = 0.0
    count = 0
    for index in range(len(numbers)):
        if isinstance(numbers[index], bool) or not isinstance(numbers[index], (int, float)):
            raise TypeError("element %d is not a number: %r" % (index, numbers[index]))
        total += numbers[index]
        count = index + 1
    if count == 0:
        return 0.0
    return total / count


def running_averages(numbers):
    """Return the mean of every prefix of numbers."""
    averages = []
    total = 0.0
    for index in range(len(numbers)):
        total += numbers[index]
        averages.append(total / (index + 1))
    return averages


def deviations(numbers, average):
    """Pair each element's position with its distance from the average."""
    spread = []
    for index in range(len(numbers)):
        spread.append((index, numbers[index] - average))
    return spread


def furthest_from_average(numbers, average):
    """Return the index of the element that deviates most from the average."""
    best_index = None
    best_distance = -1.0
    for index, offset in deviations(numbers, average):
        if abs(offset) > best_distance:
            best_distance = abs(offset)
            best_index = index
    return best_index


def format_history(history):
    """Describe each prefix mean of a data set."""
    lines = []
    for index in range(len(history)):
        lines.append("  after %d value(s): %.3f" % (index + 1, history[index]))
    return lines


def format_report(numbers):
    """Build a human readable summary of a data set."""
    average = calculate_average(numbers)
    lines = ["values: %s" % (numbers,), "average: %s" % average]
    lines.extend(format_history(running_averages(numbers)))
    outlier = furthest_from_average(numbers, average)
    if outlier is not None:
        lines.append("furthest from average: index %d (%s)" % (outlier, numbers[outlier]))
    return "\n".join(lines)


def main():
    datasets = [
        [1, 2, 3, 4, 5],
