        (list("abcabcab"), list("abc")),
        (["x", "y", "y", "z"], ["y", "y"]),
    ]
    for number in range(len(cases)):
        (main_list, sub_list) = cases[number]
        verdict = contains_sublist(main_list, sub_list)
        print("case %d: %s -> %s" % (number, describe(main_list, sub_list), verdict))

