def calculate_hamming_distance(s1, s2):
    """Count the positions at which s1 and s2 hold different characters."""
    distance = 0
    for index, char in enumerate(s1):
        if char != s2[index]:
            distance += 1
    return distance


def alignment_marks(s1, s2):
    """Build a caret/space line marking the differing columns."""
    marks = []
    for index, char in enumerate(s1):
        marks.append('^' if char != s2[index] else ' ')
    return ''.join(marks)


def describe_mismatches(s1, s2):
    """Describe each mismatch as 'at <index>: <a> -> <b>'."""
    descriptions = []
    for index, char in enumerate(s1):
        if char != s2[index]:
            descriptions.append("at %d: %s -> %s" % (index, char, s2[index]))
    return descriptions


def check_equal_length(pairs):
    """Raise ValueError naming the first pair whose strings differ in length."""
    for number, pair in enumerate(pairs):
        if len(pair[0]) != len(pair[1]):
            raise ValueError(
                "pair at index %d: lengths %d and %d differ"
                % (number, len(pair[0]), len(pair[1]))
            )


def format_report(s1, s2):
    """Produce a multi-line report for one pair of strings."""
    lines = [s1, s2, alignment_marks(s1, s2)]
    lines.append("distance = %d" % calculate_hamming_distance(s1, s2))
    descriptions = describe_mismatches(s1, s2)
    for number, description in enumerate(descriptions):
        lines.append("  %d) %s" % (number + 1, description))
    return '\n'.join(lines)


def main():
    pairs = [
        ('karolin', 'kathrin'),
        ('python', 'python'),
        ('1011101', '1001001'),
        ('GAGCCTACTAACGGGAT', 'CATCGTAATGACGGCCT'),
    ]
    check_equal_length(pairs)
    total = 0
    for number, pair in enumerate(pairs):
        print("Pair %d" % (number + 1))
        print(format_report(pair[0], pair[1]))
        total += calculate_hamming_distance(pair[0], pair[1])
        print()
    print("total distance over %d pairs: %d" % (len(pairs), total))


